@layer reset, base, tokens, recipes, utilities;

/*
 * Bodoni Moda arrives from Google Fonts a beat after first paint. Until then a
 * local Times-metric serif stands in, scaled to Bodoni's advance width and
 * line box so headlines wrap the same way and nothing jumps when it swaps.
 * (Measured: Bodoni Moda 500 runs 1.143x wider than Times; ascent 1.13em,
 * descent 0.40em. Overrides are divided by size-adjust.)
 */
@font-face {
  font-family: "Bodoni Moda Fallback";
  src: local("Times New Roman"), local("TimesNewRomanPSMT"), local("Liberation Serif"), local("Tinos");
  size-adjust: 114.3%;
  ascent-override: 98.9%;
  descent-override: 35%;
  line-gap-override: 0%;
}

/* ─── Atelier ground ────────────────────────────────────────────────────
   Pattern paper: warm stock with a faint drafting grid. Everything else in
   the house style is ink, basting thread and tailor's chalk. */
@layer base {
  :root {
    --paper: #F1ECE2;
    --ink: #1C1B19;
    --thread: #D2402A;
    --chalk: #2F55A4;
    --rule: #CFC7B8;
    --grid: rgba(28, 27, 25, 0.045);
    --ease-thread: cubic-bezier(0.22, 1, 0.36, 1);
    color-scheme: light;
  }

  /* Paper remains without WebGL; the SVG drafting grid in FabricBackdrop
     renders independently of the live linen. */
  html {
    scroll-behavior: smooth;
    color: var(--ink);
    -webkit-text-size-adjust: 100%;
    background-color: var(--paper);
  }

  body {
    font-family: 'Instrument Sans', 'Helvetica Neue', system-ui, sans-serif;
    font-size: 16px;
    line-height: 1.55;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    min-height: 100vh;
    background: transparent;
  }

  /* ─── Cursor: a needle; a dressmaker's pin over anything you can press ── */
  @media (pointer: fine) {
    html[data-cursor="needle"],
    html[data-cursor="needle"] body {
      cursor: url("/assets/cursors/needle.svg") 3 29, auto;
    }
    html[data-cursor="needle"] :is(a, button, [role="tab"], select, summary, label[for], input[type="checkbox"], input[type="radio"], input[type="range"]) {
      cursor: url("/assets/cursors/pin.svg") 4 4, pointer;
    }
    html[data-cursor="needle"] :is(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]), textarea, [contenteditable]) {
      cursor: text;
    }
    html[data-cursor="needle"] :is(button:disabled, [aria-disabled="true"]) {
      cursor: not-allowed;
    }
  }

  ::selection {
    background: #F0C534;
    color: var(--ink);
  }

  :focus-visible {
    outline: 2px solid var(--chalk);
    outline-offset: 2px;
    border-radius: 2px;
  }

  a { color: inherit; }

  /* Didone display face: tighten at size, let the optical axis do its work */
  .display {
    font-family: 'Bodoni Moda', 'Bodoni Moda Fallback', 'Didot', Georgia, serif;
    font-optical-sizing: auto;
    font-weight: 500;
    letter-spacing: -0.02em;
    line-height: 0.98;
  }

  .label {
    font-family: 'IBM Plex Mono', ui-monospace, monospace;
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.12em;
    text-transform: uppercase;
  }

  .skip-link {
    position: absolute;
    left: 12px;
    top: -60px;
    z-index: 100;
    padding: 8px 14px;
    background: var(--ink);
    color: var(--paper);
    border-radius: 4px;
    text-decoration: none;
  }
  .skip-link:focus { top: 12px; }
}

/* ─── Action verbs ──────────────────────────────────────────────────────
   Every control says what kind of thing it does before you press it, and
   answers in kind when you do (sound + press shader in fx/juice):
     cut    — commit: save, create, generate. Ink; a cut line waits underneath.
     spend  — a cut that costs credit. Ink with a tape-measure tab.
     baste  — a safe try: drafts, previews, dry runs. Loose stitches that run.
     pin    — select or toggle. A pin head appears where it will press.
     chalk  — copy, export, download. Chalk-blue, with a chalk smear.
     go     — move somewhere else. Quiet; its arrow leans the way it goes.
     unpick — remove. Thread-red, confirmed by holding.
   The hover cues are decoration on top of the label, never instead of it. */
@layer recipes {
  .act { position: relative; isolation: isolate; }

  /* cut: a dashed cut line with shears that travel along it on hover */
  .act-cut::after {
    content: "";
    position: absolute;
    left: 10px;
    right: 10px;
    bottom: 5px;
    height: 1px;
    background: linear-gradient(90deg, rgba(241, 236, 226, 0.7) 0 4px, transparent 4px 7px) 0 0 / 7px 1px repeat-x;
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.45s var(--ease-thread);
    pointer-events: none;
  }
  .act-cut:not(:disabled):hover::after { transform: scaleX(1); }

  /* spend: same cut, plus a strip of tape measure on the leading edge */
  .act-spend { padding-left: 22px !important; }
  .act-spend::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 12px;
    border-radius: inherit;
    border-top-right-radius: 0;
    border-bottom-right-radius: 0;
    background:
      repeating-linear-gradient(180deg, rgba(28, 27, 25, 0.55) 0 1px, transparent 1px 5px) right 2px top 0 / 4px 100% no-repeat,
      #F0C534;
    pointer-events: none;
  }
  .act-spend::after {
    content: "";
    position: absolute;
    left: 22px;
    right: 10px;
    bottom: 5px;
    height: 1px;
    background: linear-gradient(90deg, rgba(240, 197, 52, 0.85) 0 4px, transparent 4px 7px) 0 0 / 7px 1px repeat-x;
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.45s var(--ease-thread);
  }
  .act-spend:not(:disabled):hover::after { transform: scaleX(1); }

  /* baste: loose running stitches round the edge, which run on hover */
  .act-baste { border-color: transparent !important; }
  .act-baste::before,
  .act-unpick::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    pointer-events: none;
    --stitch: rgba(210, 64, 42, 0.75);
    background-image:
      linear-gradient(90deg, var(--stitch) 50%, transparent 0),
      linear-gradient(90deg, var(--stitch) 50%, transparent 0),
      linear-gradient(0deg, var(--stitch) 50%, transparent 0),
      linear-gradient(0deg, var(--stitch) 50%, transparent 0);
    background-size: 12px 1.5px, 12px 1.5px, 1.5px 12px, 1.5px 12px;
    background-position: 0 0, 0 100%, 0 0, 100% 0;
    background-repeat: repeat-x, repeat-x, repeat-y, repeat-y;
  }
  .act-baste:not(:disabled):hover::before {
    --stitch: var(--thread);
    animation: stitch-run 0.9s linear infinite;
  }
  @keyframes stitch-run {
    to { background-position: 12px 0, -12px 100%, 0 -12px, 100% 12px; }
  }

  /* pin: a dressmaker's pin head appears where the press will land */
  .act-pin::before {
    content: "";
    position: absolute;
    top: -4px;
    right: -4px;
    width: 9px;
    height: 9px;
    border-radius: 50%;
    background: radial-gradient(circle at 35% 30%, #F08A74, var(--thread) 55%, #8E2615);
    box-shadow: 0 1px 2px rgba(28, 27, 25, 0.35);
    transform: scale(0) translateY(-4px);
    transition: transform 0.3s var(--ease-thread);
    pointer-events: none;
    z-index: 2;
  }
  .act-pin:not(:disabled):hover::before,
  .act-pin[aria-pressed="true"]::before,
  .act-pin[aria-current="true"]::before { transform: none; }

  /* chalk: a textured chalk smear under the label */
  .act-chalk::after {
    content: "";
    position: absolute;
    left: 8px;
    right: 8px;
    bottom: 4px;
    height: 5px;
    background:
      repeating-linear-gradient(100deg, rgba(47, 85, 164, 0.35) 0 1px, transparent 1px 3px),
      linear-gradient(90deg, rgba(47, 85, 164, 0.08), rgba(47, 85, 164, 0.3) 30%, rgba(47, 85, 164, 0.18));
    border-radius: 3px 1px 4px 2px;
    transform: scaleX(0) skewX(-12deg);
    transform-origin: left;
    transition: transform 0.4s var(--ease-thread);
    pointer-events: none;
  }
  .act-chalk:not(:disabled):hover::after { transform: scaleX(1) skewX(-12deg); }

  /* go: the arrow leans toward where it goes */
  .act-go [data-arrow] { display: inline-block; transition: transform 0.3s var(--ease-thread); }
  .act-go:hover [data-arrow] { transform: translateX(3px); }
  .act-go:hover [data-arrow="out"] { transform: translate(2px, -2px); }

  /* unpick: the solid edge loosens into short stitches on hover */
  .act-unpick::before { opacity: 0; --stitch: var(--thread); background-size: 6px 1px, 6px 1px, 1px 6px, 1px 6px; transition: opacity 0.2s; }
  .act-unpick:not(:disabled):hover { border-color: transparent !important; }
  .act-unpick:not(:disabled):hover::before { opacity: 1; }

  /* working: a thread runs along the bottom edge while the action is under way */
  .act[aria-busy="true"]::after {
    content: "";
    position: absolute;
    left: 6px;
    right: 6px;
    bottom: 3px;
    height: 2px;
    transform: none;
    background: linear-gradient(90deg, var(--thread) 0 7px, transparent 7px 11px) 0 0 / 11px 2px repeat-x;
    animation: thread-run 0.6s linear infinite;
  }
  @keyframes thread-run { to { background-position: 11px 0; } }

  @media (prefers-reduced-motion: reduce) {
    .act-baste:hover::before, .act[aria-busy="true"]::after { animation: none; }
  }
}

/* ─── Basting stitch — the signature mark ───────────────────────────────
   Long loose red stitches. Used for rules, outlines and "sewn-in" reveals. */
@layer base {
  .stitch-rule {
    height: 2px;
    border: 0;
    background-image: linear-gradient(90deg, var(--thread) 0 12px, transparent 12px 20px);
    background-size: 20px 2px;
    background-repeat: repeat-x;
  }
  .stitch-rule--chalk {
    background-image: linear-gradient(90deg, var(--chalk) 0 4px, transparent 4px 9px);
    background-size: 9px 1px;
    height: 1px;
  }

  .stitch-box {
    position: relative;
  }
  .stitch-box::before {
    content: "";
    position: absolute;
    inset: -7px;
    pointer-events: none;
    border-radius: inherit;
    background:
      linear-gradient(90deg, var(--thread) 50%, transparent 0) top / 18px 1.5px repeat-x,
      linear-gradient(90deg, var(--thread) 50%, transparent 0) bottom / 18px 1.5px repeat-x,
      linear-gradient(0deg, var(--thread) 50%, transparent 0) left / 1.5px 18px repeat-y,
      linear-gradient(0deg, var(--thread) 50%, transparent 0) right / 1.5px 18px repeat-y;
    opacity: 0.9;
  }

  /* SVG thread that sews itself in when it scrolls into view */
  .thread-path {
    fill: none;
    stroke: var(--thread);
    stroke-width: 2;
    stroke-linecap: round;
    stroke-dasharray: 10 8;
  }
  .sew-in {
    animation: sew-in 1.6s var(--ease-thread) both;
  }
  @keyframes sew-in {
    from { clip-path: inset(0 100% 0 0); }
    to   { clip-path: inset(0 0 0 0); }
  }

  .rise {
    animation: rise 0.7s var(--ease-thread) both;
  }
  @keyframes rise {
    from { opacity: 0; transform: translateY(12px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  /* Scroll reveals (components/fx/reveal) — only once JS has opted in */
  .motion [data-reveal] {
    opacity: 0;
    transform: translateY(26px) rotate(var(--reveal-rot, 0deg));
    transition: opacity 0.9s var(--ease-thread), transform 1.1s var(--ease-thread);
  }
  .motion [data-reveal][data-revealed] {
    opacity: 1;
    transform: none;
  }
  .motion [data-reveal="sheet"] {
    transform: translateY(40px) rotate(-1.4deg) scale(0.98);
    transform-origin: 20% 100%;
  }
  .motion [data-reveal="sheet"][data-revealed] { transform: rotate(var(--rest-rot, 0deg)); }
  [data-depth] { translate: 0 var(--depth-y, 0); will-change: translate; }

  /* Juice: every press squashes a little and springs back past rest */
  .motion :is(button, a[class], [role="tab"], [role="radio"]):not(:disabled) {
    transition-property: transform, background-color, border-color, color, box-shadow, opacity;
  }
  .motion :is(button, [role="tab"], [role="radio"]):not(:disabled):active,
  .motion a[class]:active {
    transform: translateY(1px) scale(0.965, 0.94);
    transition-duration: 60ms;
  }
  .motion [data-juice="snip"]:not(:disabled):hover {
    animation: juice-wobble 0.5s var(--ease-thread);
  }
  @keyframes juice-wobble {
    0% { transform: rotate(0); }
    30% { transform: rotate(-1.6deg) scale(1.02); }
    60% { transform: rotate(1deg); }
    100% { transform: rotate(0); }
  }
  /* idle easter egg: a pin drops onto the page and sticks */
  .idle-pin {
    position: fixed !important;
    top: 0;
    z-index: 9000;
    animation: pin-drop 0.9s cubic-bezier(0.5, 0, 0.75, 0) both, pin-stick 0.4s 0.9s var(--ease-thread) both;
  }
  @keyframes pin-drop {
    from { transform: translateY(-40px) rotate(-30deg); }
    to   { transform: translateY(62vh) rotate(8deg); }
  }
  @keyframes pin-stick {
    0%   { transform: translateY(62vh) rotate(8deg) scale(1.15, 0.85); }
    100% { transform: translateY(62vh) rotate(0deg) scale(1); }
  }
  /* view transitions: the outgoing fitting slides off like a sheet */
  ::view-transition-old(root) { animation: 0.35s var(--ease-thread) both vt-out; }
  ::view-transition-new(root) { animation: 0.45s var(--ease-thread) both vt-in; }
  @keyframes vt-out { to { opacity: 0; transform: translateY(-8px); } }
  @keyframes vt-in { from { opacity: 0; transform: translateY(10px); } }

  /* Pinking-shears edge: the zig-zag a tailor cuts so cloth won't fray */
  .pinked {
    --pink: 9px;
    -webkit-mask:
      conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) bottom / calc(var(--pink) * 2) 51% repeat-x,
      conic-gradient(from 135deg at top, #0000, #000 1deg 89deg, #0000 90deg) top / calc(var(--pink) * 2) 51% repeat-x;
    mask:
      conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) bottom / calc(var(--pink) * 2) 51% repeat-x,
      conic-gradient(from 135deg at top, #0000, #000 1deg 89deg, #0000 90deg) top / calc(var(--pink) * 2) 51% repeat-x;
  }

  /* Dressmaker's pin, pushed through a sheet */
  .pin-head {
    position: absolute;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: radial-gradient(circle at 35% 30%, #F38A74, #D2402A 55%, #8E2615);
    box-shadow: 2px 4px 5px rgba(28, 27, 25, 0.35);
    z-index: 4;
  }
  .pin-head::after {
    content: "";
    position: absolute;
    left: 6px;
    top: 9px;
    width: 1.5px;
    height: 16px;
    background: linear-gradient(#9C978C, #6E6A61);
    transform: rotate(-28deg);
    transform-origin: top;
    z-index: -1;
  }
}

/* ─── Fitting — a scope dressed entirely in one persona's tokens ────────
   Set --f-* custom properties on the element (see lib/fitting.ts). */
@layer base {
  .fitting {
    --f-bg: #fff;
    --f-surface: #fff;
    --f-text: #111;
    --f-muted: #666;
    --f-border: #ddd;
    --f-primary: #333;
    --f-on-primary: #fff;
    --f-secondary: #555;
    --f-accent: #777;
    --f-radius: 8px;
    --f-radius-lg: 12px;
    --f-gap: 16px;
    --f-pad: 20px;
    --f-heading: inherit;
    --f-body: inherit;
    --f-mono: monospace;
    --f-ease: ease;
    --f-dur: 200ms;
    --f-border-style: solid;
    position: relative;
    isolation: isolate;
    background: var(--f-bg);
    color: var(--f-text);
    font-family: var(--f-body);
    transition:
      background-color 600ms var(--ease-thread),
      color 600ms var(--ease-thread);
  }
  .fitting * {
    transition-property: background-color, color, border-color, border-radius, padding, gap;
    transition-duration: 600ms;
    transition-timing-function: var(--ease-thread);
  }
  .fitting[data-texture="noisy"]::after,
  .fitting[data-texture="grainy"]::after,
  .fitting[data-texture="textured"]::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 5;
    pointer-events: none;
    border-radius: inherit;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.55 0'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
    mix-blend-mode: overlay;
    opacity: 0.35;
  }
  .fitting[data-texture="grainy"]::after { opacity: 0.5; }
  .fitting[data-texture="textured"]::after { opacity: 0.22; }

  .fitting .f-heading { font-family: var(--f-heading); }
  .fitting .f-mono { font-family: var(--f-mono); }
  .fitting .f-surface {
    background: var(--f-surface);
    border: 1px var(--f-border-style) var(--f-border);
    border-radius: var(--f-radius-lg);
  }
  .fitting .f-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: calc(var(--f-gap) * 0.6) calc(var(--f-gap) * 1.2);
    border-radius: var(--f-radius);
    background: var(--f-primary);
    color: var(--f-on-primary);
    font-weight: 600;
    border: 0;
    cursor: pointer;
    transition: transform var(--f-dur) var(--f-ease), filter var(--f-dur) var(--f-ease);
  }
  .fitting .f-btn:hover { transform: translateY(-1px); filter: brightness(1.06); }
  .fitting .f-btn--ghost {
    background: transparent;
    color: var(--f-text);
    border: 1px var(--f-border-style) var(--f-border);
  }
  .fitting .f-chip {
    display: inline-flex;
    align-items: center;
    padding: 3px 10px;
    border-radius: 999px;
    font-size: 12px;
    border: 1px var(--f-border-style) var(--f-border);
    color: var(--f-muted);
    background: color-mix(in oklab, var(--f-surface) 70%, var(--f-accent) 12%);
    white-space: nowrap;
  }
}

/* ─── Reduced motion: keep the craft, drop the movement ─────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}
