/* ─── Cursor vocabulary ──────────────────────────────────────────────────
   The one source of truth for every cursor on the site. Components never
   set `cursor` themselves; they use the right element or role (or a
   data-cursor hint) and inherit from here, so the same kind of target
   always answers with the same cursor:
     needle   — reading, resting. The default everywhere.
     pin      — anything you can press, pick or toggle.
     text     — anything you can type into.
     grab     — anything you can drag (data-cursor="grab"); grabbing while held.
     progress — a control or panel that is working (aria-busy).
     not-allowed — a control you cannot use right now.
   Coarse pointers keep the platform cursor. */
:root {
  --cursor-needle: url("/assets/cursors/needle.svg") 3 29, default;
  --cursor-pin: url("/assets/cursors/pin.svg") 4 4, pointer;
}
@media (pointer: fine) {
  html, body { cursor: var(--cursor-needle); }
  :is(
    a[href], button, summary, select, label[for],
    label:has(> input:is([type="checkbox"], [type="radio"])),
    label:has(input:is([type="checkbox"], [type="radio"]):not(:disabled)):is([class]),
    input:is([type="checkbox"], [type="radio"], [type="range"], [type="color"], [type="file"], [type="submit"], [type="button"], [type="reset"]),
    [role="button"], [role="link"], [role="tab"], [role="radio"], [role="checkbox"], [role="switch"], [role="option"], [role="menuitem"],
    [data-cursor="press"]
  ) {
    cursor: var(--cursor-pin);
  }
  :is(input:not([type="checkbox"], [type="radio"], [type="range"], [type="color"], [type="file"], [type="submit"], [type="button"], [type="reset"]), textarea, [contenteditable]:not([contenteditable="false"])) {
    cursor: text;
  }
  [data-cursor="grab"] { cursor: grab; }
  [data-cursor="grab"]:active, html[data-dragging] * { cursor: grabbing !important; }
  :is(button, [role="button"], [role="tab"], a[href])[aria-busy="true"],
  [aria-busy="true"]:not(button, a) { cursor: progress; }
  :is(:disabled, [aria-disabled="true"]),
  label:has(input:disabled) { cursor: not-allowed; }
}

