import { component$, useVisibleTask$ } from "@builder.io/qwik";
import Lenis from "lenis";
import Tempus from "tempus";

/**
 * Lenis smooth scroll on a single Tempus frame loop.
 *
 * Lenis owns the scroll position; Tempus runs Lenis first each frame and then
 * every scroll-driven effect (`[data-scroll]` scenes, parallax, the page seam)
 * in a fixed order, so nothing reads a stale position. Each frame publishes:
 *   --scroll-progress   0–1 down the whole page (on <html>)
 *   --scroll-velocity   signed, damped px/frame (on <html>)
 *   --scene             0–1 through each `[data-scroll]` element's pass across the viewport
 * Reduced motion and coarse pointers keep native scrolling; the variables are still set.
 */
export const SmoothScroll = component$(() => {
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    const root = document.documentElement;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const lenis = reduced
      ? null
      : new Lenis({
          autoRaf: false,
          anchors: { offset: -72 },
          lerp: 0.11,
          wheelMultiplier: 0.95,
          // Let inner scrollers (chat log, code views, studio panes) scroll natively
          allowNestedScroll: true,
          prevent: (node) => node.closest("[data-lenis-prevent], dialog, [role=dialog]") !== null,
        });
    (window as unknown as { __lenis?: Lenis | null }).__lenis = lenis;
    if (lenis) root.classList.add("lenis");

    let velocity = 0;
    const scenes = () => document.querySelectorAll<HTMLElement>("[data-scroll]");
    const depths = () => document.querySelectorAll<HTMLElement>("[data-depth]");

    const removeLenis = lenis ? Tempus.add(({ time }) => lenis.raf(time), { order: -10, label: "lenis" }) : null;
    const removeScenes = Tempus.add(
      () => {
        const vh = window.innerHeight;
        const max = root.scrollHeight - vh;
        const y = lenis ? lenis.animatedScroll : window.scrollY;
        velocity += ((lenis?.velocity ?? 0) - velocity) * 0.12;
        root.style.setProperty("--scroll-progress", (max > 0 ? y / max : 0).toFixed(4));
        root.style.setProperty("--scroll-velocity", velocity.toFixed(3));
        for (const el of scenes()) {
          const r = el.getBoundingClientRect();
          // 0 as the top edge enters at the bottom of the viewport, 1 as the bottom edge leaves the top
          const p = Math.min(1, Math.max(0, (vh - r.top) / (vh + r.height)));
          el.style.setProperty("--scene", p.toFixed(4));
        }
        if (reduced) return;
        for (const el of depths()) {
          const r = el.getBoundingClientRect();
          const center = r.top + r.height / 2 - vh / 2;
          el.style.setProperty("--depth-y", `${(-center * Number(el.dataset.depth || 0)).toFixed(1)}px`);
        }
      },
      { order: 0, label: "scroll-scenes" },
    );

    cleanup(() => {
      removeLenis?.();
      removeScenes();
      lenis?.destroy();
      root.classList.remove("lenis");
    });
  });
  return null;
});

/** Scroll to a target with Lenis when it is running, natively otherwise. */
export function scrollToTarget(target: string | HTMLElement, offset = -72) {
  const lenis = (window as unknown as { __lenis?: Lenis | null }).__lenis;
  if (lenis) return lenis.scrollTo(target, { offset });
  const el = typeof target === "string" ? document.querySelector<HTMLElement>(target) : target;
  el?.scrollIntoView({ block: "start" });
}

