import { $, component$, useComputed$, useSignal, useStore, useVisibleTask$ } from "@builder.io/qwik";
import { css } from "styled-system/css";
import type { DesignTokens, PersonaRecord } from "~/lib/api-types";
import { fittingVars } from "~/lib/fitting";
import { Garment } from "~/components/fitting/garment";
import {
  type Attachment, type Bubble, type Topic, type Turn,
  askFor, classify, greet, respond, suggestions, typingDelay, voiceOf,
} from "~/lib/converse";
import { DEFAULT_API } from "~/lib/api";

interface ConversationProps {
  personas: PersonaRecord[];
  tokens: Record<string, DesignTokens>;
  /** Persona to open with. */
  initial?: string;
}

interface Thread {
  turns: Turn[];
  covered: Topic[];
}

const STEP_NAMES = ["Measure", "Draft", "Baste", "Fit", "Cut"];
const JUDGE = [
  { k: "Persona alignment", w: 30 },
  { k: "Visual quality", w: 20 },
  { k: "Uniqueness", w: 20 },
  { k: "Coherence", w: 15 },
  { k: "Usability", w: 15 },
];

/**
 * A conversation with one of the personas, set in that persona's own fitting:
 * its palette, type, radius and motion dress the whole panel. Messages arrive
 * one at a time with a typing beat, like texting a person; each reply offers
 * the next questions worth asking, and anything can be typed instead.
 * Each persona keeps its own thread when you switch between them.
 */
export const Conversation = component$<ConversationProps>(({ personas, tokens, initial }) => {
  const activeId = useSignal(initial ?? personas[0].id);
  const threads = useStore<Record<string, Thread>>({}, { deep: true });
  const typing = useSignal(false);
  const draft = useSignal("");
  const log = useSignal<HTMLElement>();
  const input = useSignal<HTMLInputElement>();
  const live = useSignal<boolean | undefined>(undefined);
  const queue = useSignal(0);

  const persona = useComputed$(() => personas.find((p) => p.id === activeId.value) ?? personas[0]);
  const t = useComputed$(() => tokens[persona.value.id]);

  const scrollDown = $(() => {
    const el = log.value;
    if (!el) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    el.scrollTo({ top: el.scrollHeight, behavior: reduced ? "auto" : "smooth" });
  });

  /** Deliver bubbles one by one with a typing beat between them. */
  const deliver = $(async (id: string, bubbles: Bubble[]) => {
    const run = ++queue.value;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    for (let i = 0; i < bubbles.length; i++) {
      typing.value = true;
      await scrollDown();
      await new Promise((r) => setTimeout(r, reduced ? 120 : typingDelay(bubbles[i].text, i === 0)));
      if (run !== queue.value) return; // superseded by a newer message or a switch
      typing.value = false;
      threads[id].turns.push({ from: "them", ...bubbles[i] });
      await scrollDown();
    }
    typing.value = false;
  });

  const open = $(async (id: string) => {
    queue.value++;
    typing.value = false;
    activeId.value = id;
    const p = personas.find((x) => x.id === id)!;
    if (!threads[id]) {
      threads[id] = { turns: [], covered: [] };
      await deliver(id, greet(p, tokens[id]));
    } else await scrollDown();
  });

  /** Ask the server's model voice when it is available; fall back to the authored voice. */
  const answer = $(async (id: string, text: string): Promise<Bubble[]> => {
    const p = personas.find((x) => x.id === id)!;
    const thread = threads[id];
    const local = respond(p, tokens[id], text, thread.covered);
    thread.covered.push(local.topic);
    if (live.value === false || local.topic === "thanks") return local.bubbles;
    try {
      const res = await fetch(`${DEFAULT_API}/converse/${encodeURIComponent(id)}`, {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ handle: voiceOf(id).handle, turns: thread.turns.map(({ from, text }) => ({ from, text })) }),
        signal: AbortSignal.timeout(20_000),
      });
      if (!res.ok) throw new Error(String(res.status));
      const { bubbles } = (await res.json()) as { bubbles: string[] };
      live.value = true;
      // Keep the authored attachment so the design still shows up alongside the words
      const attach = local.bubbles.find((b) => b.attach)?.attach;
      return bubbles.map((text, i) => ({ text, attach: i === bubbles.length - 1 ? attach : undefined }));
    } catch {
      live.value = false;
      return local.bubbles;
    }
  });

  const send = $(async (text: string) => {
    const clean = text.trim();
    if (!clean) return;
    const id = activeId.value;
    draft.value = "";
    queue.value++;
    threads[id].turns.push({ from: "you", text: clean });
    typing.value = true;
    await scrollDown();
    const bubbles = await answer(id, clean);
    if (activeId.value === id) await deliver(id, bubbles);
    else threads[id].turns.push(...bubbles.map((b) => ({ from: "them" as const, ...b })));
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async () => {
    await open(activeId.value);
  }, { strategy: "intersection-observer" });

  const thread = threads[persona.value.id];
  const voice = voiceOf(persona.value.id);
  const next = suggestions(thread?.covered ?? []);
  const vars = fittingVars(persona.value, t.value);

  return (
    <div class={css({ display: "flex", flexDirection: "column", gap: 4, minW: 0 })}>
      {/* Who to talk to */}
      <div role="tablist" aria-label="Talk to" class={css({ display: "flex", gap: 2, flexWrap: "wrap" })}>
        {personas.map((p) => {
          const v = voiceOf(p.id);
          const pt = tokens[p.id];
          const selected = p.id === activeId.value;
          return (
            <button
              key={p.id}
              type="button"
              role="tab"
              id={`talk-${p.id}`}
              aria-selected={selected}
              aria-controls="conversation-panel"
              data-juice="pin"
              onClick$={() => open(p.id)}
              class={css({
                display: "inline-flex", alignItems: "center", gap: 2.5, pl: 1.5, pr: 4, h: "44px", rounded: "full",
                border: "1px solid token(colors.rule-strong)", bg: "card", fontSize: "14px", color: "ink-soft",
                transition: "all 0.25s token(easings.thread)",
                _hover: { color: "ink", borderColor: "ink" },
                "&[aria-selected=true]": { bg: "ink", color: "paper", borderColor: "ink", boxShadow: "sheet" },
              })}
            >
              <Avatar persona={p} tokens={pt} size={32} />
              <span class={css({ display: "flex", flexDirection: "column", alignItems: "start", lineHeight: 1.15 })}>
                <span class={css({ fontWeight: 600 })}>{v.handle}</span>
                <span class={css({ fontSize: "11px", opacity: 0.7 })}>{p.name.replace(/^The /, "")}</span>
              </span>
            </button>
          );
        })}
      </div>

      {/* The phone-ish panel, dressed in the persona's fitting */}
      <section
        id="conversation-panel"
        role="tabpanel"
        aria-labelledby={`talk-${persona.value.id}`}
        class={`fitting ${css({ display: "flex", flexDirection: "column", h: { base: "560px", md: "620px" }, overflow: "hidden", boxShadow: "lift", minW: 0 })}`}
        style={{ ...vars, borderRadius: "var(--f-radius-lg)", border: "1px var(--f-border-style) var(--f-border)" }}
        data-texture={persona.value.aesthetic.textureStyle}
      >
        <header class={css({ display: "flex", alignItems: "center", gap: 3, px: 4, py: 3, borderBottom: "1px solid var(--f-border)", bg: "var(--f-surface)" })}>
          <Avatar persona={persona.value} tokens={t.value} size={40} />
          <div class={css({ display: "flex", flexDirection: "column", minW: 0, flex: 1 })}>
            <span class="f-heading" style={{ fontSize: "19px", lineHeight: 1.1 }}>{voice.handle}</span>
            <span class={css({ fontSize: "12px", color: "var(--f-muted)", display: "flex", alignItems: "center", gap: 1.5 })}>
              <i aria-hidden="true" class={css({ w: "7px", h: "7px", rounded: "full" })} style={{ background: "var(--f-accent)" }} />
              {typing.value ? "typing…" : voice.status}
            </span>
          </div>
          <span class={`f-mono ${css({ fontSize: "11px", color: "var(--f-muted)", textAlign: "right", display: { base: "none", sm: "block" } })}`}>
            {live.value ? "live voice" : "persona"}
            <br />
            {persona.value.aesthetic.density} · {persona.value.aesthetic.motionStyle}
          </span>
        </header>

        <div
          ref={log}
          data-lenis-prevent
          role="log"
          aria-live="polite"
          aria-relevant="additions"
          aria-label={`Conversation with ${voice.handle}`}
          class={css({ flex: 1, overflowY: "auto", overscrollBehavior: "contain", px: { base: 3, md: 5 }, py: 5, display: "flex", flexDirection: "column", gap: 2 })}
        >
          {thread?.turns.map((turn, i) => {
            const prev = thread.turns[i - 1];
            const grouped = prev?.from === turn.from;
            return (
              <div key={i} class="msg-in" data-from={turn.from} style={{ marginTop: grouped ? "0" : "10px" }}>
                <div class={css({ display: "flex", flexDirection: "column", gap: 2, alignItems: turn.from === "you" ? "end" : "start" })}>
                  <p
                    class={css({ maxW: "min(46ch, 86%)", px: 3.5, py: 2.5, fontSize: "15px", lineHeight: 1.45, overflowWrap: "anywhere" })}
                    style={
                      turn.from === "you"
                        ? { background: "var(--f-primary)", color: "var(--f-on-primary)", borderRadius: "var(--f-radius-lg) var(--f-radius-lg) var(--f-radius-sm) var(--f-radius-lg)" }
                        : { background: "var(--f-surface)", color: "var(--f-text)", border: "1px var(--f-border-style) var(--f-border)", borderRadius: "var(--f-radius-lg) var(--f-radius-lg) var(--f-radius-lg) var(--f-radius-sm)" }
                    }
                  >
                    {turn.text}
                  </p>
                  {turn.attach && <AttachmentView a={turn.attach} persona={persona.value} tokens={t.value} />}
                </div>
              </div>
            );
          })}
          {typing.value && (
            <div class="msg-in" aria-label={`${voice.handle} is typing`} role="status">
              <span class={css({ display: "inline-flex", gap: 1, px: 3.5, py: 3, mt: 2 })} style={{ background: "var(--f-surface)", border: "1px var(--f-border-style) var(--f-border)", borderRadius: "var(--f-radius-lg)" }}>
                <i class="typing-dot" /><i class="typing-dot" /><i class="typing-dot" />
              </span>
            </div>
          )}
        </div>

        <footer class={css({ borderTop: "1px solid var(--f-border)", bg: "var(--f-surface)", px: 3, pt: 3, pb: 3, display: "flex", flexDirection: "column", gap: 2.5 })}>
          {!typing.value && next.length > 0 && (
            <div class={css({ display: "flex", gap: 2, flexWrap: "wrap" })} aria-label="Suggested questions">
              {next.map((s) => (
                <button
                  key={s.topic}
                  type="button"
                  class="f-chip suggest"
                  data-juice="baste"
                  onClick$={() => send(s.label)}
                >
                  {s.label}
                </button>
              ))}
            </div>
          )}
          <form
            preventdefault:submit
            onSubmit$={() => send(draft.value)}
            class={css({ display: "flex", gap: 2, alignItems: "center" })}
          >
            <label for="converse-input" class={css({ srOnly: true })}>Message {voice.handle}</label>
            <input
              ref={input}
              id="converse-input"
              type="text"
              autoComplete="off"
              maxLength={600}
              placeholder={`Ask ${voice.handle} anything…`}
              value={draft.value}
              onInput$={(_, el) => (draft.value = el.value)}
              class={css({ flex: 1, minW: 0, h: "44px", px: 4, fontSize: "15px", outline: "none", _focusVisible: { boxShadow: "0 0 0 2px var(--f-accent)" } })}
              style={{ background: "var(--f-bg)", color: "var(--f-text)", border: "1px var(--f-border-style) var(--f-border)", borderRadius: "var(--f-radius)" }}
            />
            <button
              type="submit"
              class="f-btn"
              data-juice="snip"
              disabled={!draft.value.trim()}
              aria-label="Send"
              style={{ height: "44px", opacity: draft.value.trim() ? 1 : 0.5 }}
            >
              Send
            </button>
          </form>
        </footer>
      </section>
      <p class={css({ fontSize: "12.5px", color: "ink-muted" })}>
        {voice.handle} is a persona, an authored character built from cultural measurements, not a real person or user research.
        {live.value ? " Replies come from your local Baste server's model." : " Replies are written from the persona's own data and work offline."}
      </p>
    </div>
  );
});

/** A monogram in the persona's own colours and display face: no stock faces. */
export const Avatar = component$<{ persona: PersonaRecord; tokens: DesignTokens; size: number }>(({ persona, tokens, size }) => {
  const v = voiceOf(persona.id);
  return (
    <span
      aria-hidden="true"
      class={css({ display: "grid", placeItems: "center", rounded: "full", flexShrink: 0, overflow: "hidden", position: "relative" })}
      style={{
        width: `${size}px`, height: `${size}px`,
        background: `radial-gradient(circle at 30% 25%, ${tokens.colors.accent}, ${tokens.colors.primary} 60%, ${tokens.colors.background})`,
        color: tokens.colors.background,
        fontFamily: tokens.typography.fontFamily.heading,
        fontSize: `${Math.round(size * 0.5)}px`,
        boxShadow: `inset 0 0 0 1.5px ${tokens.colors.surface}`,
      }}
    >
      {v.handle.charAt(0)}
    </span>
  );
});

const AttachmentView = component$<{ a: Attachment; persona: PersonaRecord; tokens: DesignTokens }>(({ a, persona, tokens }) => {
  const card = css({ maxW: "min(420px, 92%)", p: 3, display: "flex", flexDirection: "column", gap: 2 });
  const cardStyle = { background: "var(--f-surface)", border: "1px var(--f-border-style) var(--f-border)", borderRadius: "var(--f-radius-lg)" };
  switch (a.kind) {
    case "palette":
      return (
        <div class={card} style={cardStyle}>
          <div class={css({ display: "grid", gridTemplateColumns: "repeat(6, 1fr)", gap: 1.5 })}>
            {a.swatches.map((s) => (
              <span key={s.role} class={css({ display: "flex", flexDirection: "column", gap: 1 })}>
                <i class={css({ h: "38px", display: "block" })} style={{ background: s.hex, borderRadius: "var(--f-radius-sm)", border: "1px solid var(--f-border)" }} />
                <span class="f-mono" style={{ fontSize: "9.5px", color: "var(--f-muted)" }}>{s.hex.toUpperCase()}</span>
              </span>
            ))}
          </div>
        </div>
      );
    case "type":
      return (
        <div class={card} style={cardStyle}>
          <span class="f-heading" style={{ fontSize: "34px", lineHeight: 1 }}>Aa — {a.heading}</span>
          <span style={{ fontSize: "14px", color: "var(--f-muted)" }}>{a.body}: the quick brown fox reads the whole manual.</span>
        </div>
      );
    case "garment":
      return (
        <div class={css({ w: "min(440px, 92%)", pointerEvents: "none" })} aria-label="A screen in this fitting" role="img">
          <div style={{ transform: "scale(0.86)", transformOrigin: "top left", width: "116%", marginBottom: "-14%" }}>
            <Garment persona={persona} tokens={tokens} size="compact" />
          </div>
        </div>
      );
    case "steps":
      return (
        <ol class={card} style={{ ...cardStyle, flexDirection: "row", gap: "6px", listStyle: "none" }} aria-label="Baste's method">
          {STEP_NAMES.map((n, i) => (
            <li
              key={n}
              class={css({ flex: 1, textAlign: "center", fontSize: "11.5px", py: 2, px: 1 })}
              style={{
                borderRadius: "var(--f-radius)",
                background: i === a.active ? "var(--f-primary)" : "transparent",
                color: i === a.active ? "var(--f-on-primary)" : "var(--f-muted)",
                border: "1px var(--f-border-style) var(--f-border)",
              }}
            >
              <span class="f-mono" style={{ display: "block", fontSize: "10px", opacity: 0.8 }}>0{i + 1}</span>
              {n}
            </li>
          ))}
        </ol>
      );
    case "judge":
      return (
        <div class={card} style={cardStyle}>
          {JUDGE.map((j, i) => (
            <div key={j.k} class={css({ display: "grid", gridTemplateColumns: "1fr 90px 34px", gap: 2, alignItems: "center", fontSize: "12.5px" })}>
              <span>{j.k}</span>
              <span style={{ height: "6px", background: "var(--f-border)", borderRadius: "99px", overflow: "hidden" }}>
                <i style={{ display: "block", height: "100%", width: `${j.w * 3.33}%`, background: i === 0 ? "var(--f-accent)" : "var(--f-primary)" }} />
              </span>
              <span class="f-mono" style={{ textAlign: "right", color: "var(--f-muted)" }}>{j.w}%</span>
            </div>
          ))}
        </div>
      );
    case "link":
      return (
        <a href={a.href} class="f-btn f-btn--ghost" style={{ fontSize: "13.5px", padding: "8px 14px" }}>
          {a.label} <span aria-hidden="true">→</span>
        </a>
      );
  }
});

