import { chromium } from 'playwright';
import assert from 'node:assert/strict';
const browser=await chromium.launch({executablePath:'/usr/bin/google-chrome',args:['--use-angle=swiftshader','--enable-unsafe-swiftshader']});
const base='http://localhost:5184';
try {
 for(const mode of ['desktop','mobile']) {
  const mobile=mode==='mobile';
  const page=await browser.newPage({viewport:mobile?{width:390,height:844}:{width:1440,height:960},isMobile:mobile,hasTouch:mobile,deviceScaleFactor:1,serviceWorkers:'block',reducedMotion:'reduce'});
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.route('**/api/health',r=>r.fulfill({json:{conversation:{mode:'demo'}}}));
  await page.goto(base+'/#meet',{waitUntil:'networkidle'});
  await page.evaluate(()=>document.fonts.ready);
  await page.waitForFunction(()=>[...document.querySelectorAll('.companion-portrait')].every(i=>i.complete&&i.naturalWidth>0));
  await page.evaluate(()=>window.scrollTo({top:document.querySelector('#meet').getBoundingClientRect().top+scrollY-76,behavior:'instant'}));
  await page.screenshot({path:`/tmp/baste-companion-${mode}.png`});
  if(mobile){
   await page.evaluate(()=>window.scrollTo({top:document.querySelector('.companion-dialogue').getBoundingClientRect().top+scrollY-78,behavior:'instant'}));
   await page.screenshot({path:'/tmp/baste-companion-mobile-reply.png'});
  } else {
   await page.getByRole('button',{name:'Why these colours?',exact:false}).click();
   await page.getByRole('log').getByText(/That bright mint/).waitFor();
   await page.waitForFunction(()=>!document.querySelector('[aria-label="Moss is typing"]'));
   await page.screenshot({path:'/tmp/baste-companion-desktop-palette.png'});
  }
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  const measured=await page.locator('.companion-dialogue').evaluate(el=>({height:el.getBoundingClientRect().height,opacity:getComputedStyle(el).opacity,display:getComputedStyle(el).display,composer:getComputedStyle(el.querySelector('textarea')).fontSize}));
  assert.equal(measured.opacity,'1');assert.equal(measured.composer,'16px');assert.deepEqual(errors,[]);
  console.log(JSON.stringify({mode,measured,errors}));
  await page.close();
 }
} finally {await browser.close();}


