/* ─── Fitting — a scope dressed entirely in one persona's tokens ────────
   Set --f-* custom properties on the element (see lib/fitting.ts). */
@layer base {
  .fitting {
    --f-bg: #fff;
    --f-surface: #fff;
    --f-text: #111;
    --f-muted: #666;
    --f-border: #ddd;
