    --f-on-primary: #fff;
    --f-secondary: #555;
    --f-accent: #777;
    --f-radius: 8px;
    --f-radius-lg: 12px;
    --f-gap: 16px;
    --f-pad: 20px;
    --f-heading: inherit;
    --f-body: inherit;
    --f-mono: monospace;
    --f-ease: ease;
    --f-dur: 200ms;
    --f-border-style: solid;
    position: relative;
    isolation: isolate;
    background: var(--f-bg);
    color: var(--f-text);
    font-family: var(--f-body);
    transition:
      background-color 600ms var(--ease-thread),
      color 600ms var(--ease-thread);
  }
  .fitting * {
    transition-property: background-color, color, border-color, border-radius, padding, gap;
    transition-duration: 600ms;
    transition-timing-function: var(--ease-thread);
  }
  .fitting[data-texture="noisy"]::after,
  .fitting[data-texture="grainy"]::after,
  .fitting[data-texture="textured"]::after {
    content: "";
    position: absolute;
    inset: 0;
