import { $, component$, sync$, useSignal, useStyles$, useVisibleTask$ } from "@builder.io/qwik";
import type { DesignTokens, PersonaRecord } from "~/lib/api-types";
import { primaryFamily } from "~/lib/fonts";
import { voiceOf } from "~/lib/converse";
import fittings from "~/lib/fittings.json";
import { Fabric, lookFromTokens } from "~/components/fx/fabric";
import { Garment } from "./garment";
import styles from "./fitting-room.css?inline";

interface FittingRoomProps {
  personas: PersonaRecord[];
  tokens: Record<string, DesignTokens>;
  /** Auto-advance between personas until the visitor picks one. */
  autoplay?: boolean;
  /** Show the spec rail: tokens, generated icons and the archive spread. */
  showMeasurements?: boolean;
}

interface ArchiveCell {
  src: string;
  cell: string;
  features: number[];
  quality: number;
}

interface Art {
  icon?: { src: string; score: number };
  "icon-collection"?: { src: string; score: number };
  archive?: ArchiveCell[];
  run?: { candidates: number; generations: number };
}

/**
 * One interface, fitted live to each persona. The screen is pinned to a bolt
 * of cloth dyed in that persona's colours; the spec rail beside it reads like
 * a designer's redline — the faces, swatches, radius and motion that changed,
 * the icons Baste drew for them, and the spread of variants its search kept.
 */
export const FittingRoom = component$<FittingRoomProps>(({ personas, tokens, autoplay = true, showMeasurements = true }) => {
  useStyles$(styles);
  const index = useSignal(0);
  const touched = useSignal(false);
  const stage = useSignal<HTMLDivElement>();

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (autoplay && !reduced) {
      const id = setInterval(() => {
        if (!touched.value) index.value = (index.value + 1) % personas.length;
      }, 5600);
      cleanup(() => clearInterval(id));
    }
    // Pointer tilt: the pinned screen leans toward the cursor.
    const el = stage.value;
    if (!el || reduced || !window.matchMedia("(pointer: fine)").matches) return;
    let raf = 0;
    const onMove = (e: PointerEvent) => {
      const r = el.getBoundingClientRect();
      const x = (e.clientX - r.left) / r.width - 0.5;
      const y = (e.clientY - r.top) / r.height - 0.5;
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        el.style.setProperty("--tilt-x", `${(-y * 4).toFixed(2)}deg`);
        el.style.setProperty("--tilt-y", `${(x * 6).toFixed(2)}deg`);
        el.style.setProperty("--shift-x", `${(x * -12).toFixed(1)}px`);
        el.style.setProperty("--shift-y", `${(y * -8).toFixed(1)}px`);
      });
    };
    const onLeave = () => {
      for (const p of ["--tilt-x", "--tilt-y", "--shift-x", "--shift-y"]) el.style.removeProperty(p);
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);
    cleanup(() => {
      cancelAnimationFrame(raf);
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
    });
  });

  const pick = $((i: number) => {
    touched.value = true;
    index.value = i;
  });

  const persona = personas[index.value];
  const t = tokens[persona.id];
  const a = persona.aesthetic;
  const art = (fittings as Record<string, Art>)[persona.id] ?? {};
  const swatches = (["background", "surface", "primary", "secondary", "accent", "text"] as const).map((role) => ({ role, hex: t.colors[role] }));

  return (
    <div class="fitting-room" data-measurements={showMeasurements ? "true" : "false"}>
      <div role="tablist" aria-label="Fit for persona" class="fitting-tabs">
        {personas.map((p, i) => {
          const pt = tokens[p.id];
          const selected = i === index.value;
          return (
            <button
              key={p.id}
              type="button"
              role="tab"
              id={`fit-${p.id}`}
              tabIndex={selected ? 0 : -1}
              aria-selected={selected}
              aria-controls="fitting-panel"
              data-juice="pin"
              onClick$={() => pick(i)}
              onKeyDown$={[sync$((event: KeyboardEvent) => {
                if (["Home", "End", "ArrowRight", "ArrowLeft"].includes(event.key)) event.preventDefault();
              }), $(async (event: KeyboardEvent) => {
                const next = event.key === "Home" ? 0 : event.key === "End" ? personas.length - 1 : event.key === "ArrowRight" ? (i + 1) % personas.length : event.key === "ArrowLeft" ? (i + personas.length - 1) % personas.length : -1;
                if (next < 0) return;
                await pick(next);
                document.getElementById(`fit-${personas[next].id}`)?.focus();
              })]}
              class="fitting-tab"
              style={{ "--tab-primary": pt.colors.primary, "--tab-accent": pt.colors.accent }}
            >
              <img src={`/assets/companions/${p.id}.webp`} alt="" width={40} height={40} loading="lazy" decoding="async" />
              <span>
                <strong>{voiceOf(p.id).handle}</strong>
                <small>{p.name.replace(/^The /, "")}</small>
              </span>
              {autoplay && selected && !touched.value && <i class="fitting-tab-timer" aria-hidden="true" />}
            </button>
          );
        })}
      </div>

      <div class="fitting-stage-grid">
        <div ref={stage} class="fitting-stage">
          <div aria-hidden="true" class="fitting-cloth">
            <div class="pinked fitting-cloth-cut">
              <Fabric look={lookFromTokens(t, a.density)} quality={0.75} label={`${persona.name} cloth`} />
            </div>
          </div>
          <div id="fitting-panel" role="tabpanel" aria-labelledby={`fit-${persona.id}`} class="fitting-garment">
            <span class="pin-head" style={{ left: "-6px", top: "-6px" }} aria-hidden="true" />
            <span class="pin-head" style={{ right: "22px", top: "-7px" }} aria-hidden="true" />
            <Garment persona={persona} tokens={t} />
          </div>
        </div>

        {showMeasurements && (
          <aside class="fitting-spec" aria-label={`Measurements for ${persona.name}`}>
            <section>
              <h3 class="fitting-spec-title">Type</h3>
              <div class="fitting-type">
                <span class="fitting-type-sample" style={{ fontFamily: t.typography.fontFamily.heading }}>Aa</span>
                <dl>
                  <div><dt>Display</dt><dd>{primaryFamily(t.typography.fontFamily.heading)}</dd></div>
                  <div><dt>Text</dt><dd>{primaryFamily(t.typography.fontFamily.body)}</dd></div>
                </dl>
              </div>
            </section>
            <section>
              <h3 class="fitting-spec-title">Colour</h3>
              <ul class="fitting-swatches">
                {swatches.map((s) => (
                  <li key={s.role}>
                    <i style={{ background: s.hex }} />
                    <span>{s.role}</span>
                    <code>{s.hex.toUpperCase()}</code>
                  </li>
                ))}
              </ul>
            </section>
            <section class="fitting-metrics">
              <div>
                <h3 class="fitting-spec-title">Radius</h3>
                <span class="fitting-radius" style={{ borderRadius: t.borders.radius.lg }} aria-hidden="true" />
                <code>{t.borders.radius.base} · {a.edgeStyle}</code>
              </div>
              <div>
                <h3 class="fitting-spec-title">Motion</h3>
                <span class="fitting-motion" style={{ "--motion": t.motion.duration.slow, "--ease": t.motion.easing.default }} aria-hidden="true"><i /></span>
                <code>{t.motion.duration.base} · {a.motionStyle}</code>
              </div>
            </section>
            {(art.icon || art["icon-collection"]) && (
              <section>
                <h3 class="fitting-spec-title">Icons drawn for {voiceOf(persona.id).handle}</h3>
                <div class="fitting-icons">
                  {[art.icon, art["icon-collection"]].filter(Boolean).map((icon) => (
                    <img key={icon!.src} src={icon!.src} alt="" width={72} height={72} loading="lazy" decoding="async" />
                  ))}
                </div>
              </section>
            )}
            {art.archive && art.archive.length > 1 && (
              <section>
                <h3 class="fitting-spec-title">
                  {art.archive.length} variants kept from {art.run?.candidates} tried
                </h3>
                <ul class="fitting-archive">
                  {art.archive.slice(0, 8).map((c) => (
                    <li key={c.src} title={`Judge ${Math.round(c.quality * 100)} · ${c.features[0] > 0 ? "warm" : "cool"}`}>
                      <img src={c.src} alt="" width={720} height={405} loading="lazy" decoding="async" />
                    </li>
                  ))}
                </ul>
                <a class="fitting-spec-link" href="/method/#archive">How the archive is searched <span aria-hidden="true">→</span></a>
              </section>
            )}
          </aside>
        )}
      </div>
    </div>
  );
});

/* ─── Fitting room: persona tabs, the pinned screen, and the spec rail ─────── */

.fitting-room { display: flex; flex-direction: column; gap: 22px; min-width: 0; }

/* Persona tabs: a portrait, a name, the persona's own colours as a seam */
.fitting-tabs { display: flex; gap: 8px; flex-wrap: wrap; }
.fitting-tab {
  position: relative;
  display: inline-flex; align-items: center; gap: 10px;
  padding: 5px 16px 5px 5px; min-height: 52px;
  border: 1px solid #CFC7B8; border-radius: 999px;
  background: #FBF9F4; color: #45423C;
  font: inherit; text-align: left;
  transition: border-color .25s var(--ease-thread), background .25s var(--ease-thread), color .25s var(--ease-thread), box-shadow .25s var(--ease-thread);
}
.fitting-tab img { width: 40px; height: 40px; border-radius: 50%; object-fit: cover; box-shadow: 0 0 0 2px #FBF9F4, 0 0 0 3px var(--tab-primary); }
.fitting-tab span { display: flex; flex-direction: column; line-height: 1.15; }
.fitting-tab strong { font-size: 14px; color: #1C1B19; }
.fitting-tab small { font-size: 11.5px; color: #6E6A61; }
.fitting-tab:hover { border-color: #1C1B19; }
.fitting-tab[aria-selected="true"] {
  background: #1C1B19; border-color: #1C1B19; color: #F1ECE2;
  box-shadow: 0 1px 0 rgba(28,27,25,.06), 0 10px 22px -14px rgba(60,45,20,.5);
}
.fitting-tab[aria-selected="true"] strong { color: #F1ECE2; }
.fitting-tab[aria-selected="true"] small { color: #CFC7B8; }
.fitting-tab[aria-selected="true"] img { box-shadow: 0 0 0 2px #1C1B19, 0 0 0 3px var(--tab-accent); }
.fitting-tab:focus-visible { outline: 2px solid #2F55A4; outline-offset: 3px; }
.fitting-tab-timer {
  position: absolute; left: 24px; right: 24px; bottom: -1px; height: 2px; border-radius: 2px;
  background: #F0C534; transform-origin: left; animation: fitting-timer 5.6s linear;
}
@keyframes fitting-timer { from { transform: scaleX(0); } to { transform: scaleX(1); } }

/* Stage + spec rail */
.fitting-stage-grid { display: grid; gap: 28px; align-items: start; }
.fitting-room[data-measurements="true"] .fitting-stage-grid { grid-template-columns: minmax(0, 1fr) minmax(220px, 260px); }

.fitting-stage { position: relative; padding: 26px 30px 34px 22px; perspective: 1400px; }
.fitting-cloth {
  position: absolute; inset: 0; z-index: 0;
  transform: rotate(-1.4deg) translate(var(--shift-x, 0), var(--shift-y, 0));
  transition: transform .8s var(--ease-thread);
}
.fitting-cloth-cut { position: absolute; inset: 0; filter: drop-shadow(0 18px 24px rgba(60,45,20,.24)); }
.fitting-garment {
  position: relative; z-index: 1;
  transform: rotateX(var(--tilt-x, 0deg)) rotateY(var(--tilt-y, 0deg)) rotate(.4deg);
  transform-style: preserve-3d;
  transition: transform .5s var(--ease-thread);
  box-shadow: 0 1px 0 rgba(28,27,25,.06), 0 30px 50px -28px rgba(30,22,10,.55);
  border-radius: 16px;
}
.fitting-garment .garment { animation: fitting-in .55s var(--ease-thread); }
@keyframes fitting-in { from { opacity: .4; transform: translateY(6px) scale(.992); } }

/* The spec rail reads like a redline on the pattern */
.fitting-spec {
  display: flex; flex-direction: column; gap: 18px;
  padding: 18px 0 0 18px; border-left: 1.5px dashed #2F55A4;
  font-size: 12.5px; color: #45423C;
}
.fitting-spec section { display: flex; flex-direction: column; gap: 8px; }
.fitting-spec-title {
  margin: 0; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 10.5px; font-weight: 500;
  letter-spacing: .12em; text-transform: uppercase; color: #2F55A4;
}
.fitting-spec code, .fitting-spec dd { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 11.5px; color: #1C1B19; margin: 0; }
.fitting-type { display: flex; align-items: center; gap: 14px; }
.fitting-type-sample { font-size: 46px; line-height: 1; color: #1C1B19; min-width: 64px; transition: font-family 0s; }
.fitting-type dl { margin: 0; display: grid; gap: 4px; }
.fitting-type dl div { display: grid; grid-template-columns: 52px 1fr; }
.fitting-type dt { color: #6E6A61; }

.fitting-swatches { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px 6px; }
.fitting-swatches li { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.fitting-swatches i { display: block; height: 28px; border-radius: 6px; box-shadow: inset 0 0 0 1px rgba(28,27,25,.14); transition: background .6s var(--ease-thread); }
.fitting-swatches span { font-size: 10.5px; color: #6E6A61; text-transform: capitalize; }
.fitting-swatches code { font-size: 10.5px; }

.fitting-metrics { display: grid !important; grid-template-columns: 1fr 1fr; gap: 12px; }
.fitting-metrics > div { display: flex; flex-direction: column; gap: 8px; }
.fitting-radius { width: 42px; height: 30px; border: 1.5px solid #1C1B19; border-left-color: transparent; border-bottom-color: transparent; transition: border-radius .6s var(--ease-thread); }
.fitting-motion { position: relative; width: 100%; height: 30px; border-bottom: 1px dashed #A79E8D; }
.fitting-motion i {
  position: absolute; left: 0; bottom: -4px; width: 8px; height: 8px; border-radius: 50%; background: #D2402A;
  animation: fitting-motion calc(var(--motion) * 2.4) var(--ease) infinite alternate;
}
@keyframes fitting-motion { to { left: calc(100% - 8px); } }

.fitting-icons { display: flex; gap: 8px; }
.fitting-icons img { width: 64px; height: 64px; border-radius: 12px; background: #fff; box-shadow: inset 0 0 0 1px rgba(28,27,25,.1); padding: 4px; }

.fitting-archive { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px; }
.fitting-archive li { aspect-ratio: 16 / 10; border-radius: 4px; overflow: hidden; box-shadow: inset 0 0 0 1px rgba(28,27,25,.1); }
.fitting-archive img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform .4s var(--ease-thread); }
.fitting-archive li:hover img { transform: scale(1.06); }
.fitting-spec-link { color: #2F55A4; font-size: 12px; text-decoration: none; }
.fitting-spec-link:hover { text-decoration: underline; text-underline-offset: 3px; }

@media (max-width: 1100px) {
  .fitting-room[data-measurements="true"] .fitting-stage-grid { grid-template-columns: minmax(0, 1fr); }
  .fitting-spec { border-left: 0; border-top: 1.5px dashed #2F55A4; padding: 16px 0 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }
}
@media (max-width: 640px) {
  .fitting-stage { padding: 14px 12px 22px 10px; }
  .fitting-tab { padding-right: 12px; }
  .fitting-tab small { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .fitting-garment .garment, .fitting-motion i, .fitting-tab-timer { animation: none; }
  .fitting-cloth, .fitting-garment { transition: none; }
}

