// Record real Baste screens for the tour, one webm per scene, at 1920x1080.
// A drawn cursor is injected so viewers can follow each interaction.
import { chromium } from 'playwright';
import { mkdirSync, renameSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const OUT = process.argv[2];
const only = process.argv[3];
mkdirSync(OUT, { recursive: true });
const SITE = 'http://127.0.0.1:5173';
const W = 1920, H = 1080;
const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--autoplay-policy=no-user-gesture-required'] });

const CURSOR = `
  (() => {
    if (document.getElementById('tour-cursor')) return;
    const c = document.createElement('div');
    c.id = 'tour-cursor';
    c.innerHTML = '<svg width="26" height="30" viewBox="0 0 26 30"><path d="M3 2 L3 24 L9 18.5 L13.5 28 L17.5 26.2 L13 17 L21 17 Z" fill="#1C1B19" stroke="#F1ECE2" stroke-width="2" stroke-linejoin="round"/></svg>';
    Object.assign(c.style, { position: 'fixed', left: '0', top: '0', zIndex: 2147483647, pointerEvents: 'none', transform: 'translate(-100px,-100px)', transition: 'transform 60ms linear', filter: 'drop-shadow(0 2px 3px rgba(0,0,0,.35))' });
    const ring = document.createElement('div');
    Object.assign(ring.style, { position: 'fixed', left: '-22px', top: '-22px', width: '44px', height: '44px', borderRadius: '50%', border: '2px solid #D2402A', zIndex: 2147483646, pointerEvents: 'none', opacity: '0', transform: 'translate(-100px,-100px) scale(.4)' });
    document.documentElement.append(ring, c);
    addEventListener('pointermove', e => { c.style.transform = 'translate(' + e.clientX + 'px,' + e.clientY + 'px)'; }, true);
    addEventListener('pointerdown', e => {
      ring.animate([{ opacity: .9, transform: 'translate(' + e.clientX + 'px,' + e.clientY + 'px) scale(.4)' }, { opacity: 0, transform: 'translate(' + e.clientX + 'px,' + e.clientY + 'px) scale(1.4)' }], { duration: 520, easing: 'ease-out' });
    }, true);
  })();`;

async function scene(name, url, act, { demo = false } = {}) {
  if (only && only !== name) return;
  const dir = join(OUT, `.${name}`);
  const ctx = await browser.newContext({ viewport: { width: W, height: H }, deviceScaleFactor: 1, recordVideo: { dir, size: { width: W, height: H } } });
  const page = await ctx.newPage();
  if (demo) await page.route('**/api/**', r => r.abort());
  await page.addInitScript(CURSOR);
  let x = W / 2, y = H / 2;
  const move = async (tx, ty, steps = 28) => {
    for (let i = 1; i <= steps; i++) {
      const t = i / steps, e = t < .5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2;
      await page.mouse.move(x + (tx - x) * e, y + (ty - y) * e);
      await page.waitForTimeout(16);
    }
    x = tx; y = ty;
  };
  const point = async (locator, dx = .5, dy = .5) => {
    const b = await locator.boundingBox();
    if (!b) throw new Error(`${name}: target not visible`);
    await move(b.x + b.width * dx, b.y + b.height * dy);
  };
  const click = async (locator) => { await point(locator); await page.waitForTimeout(160); await page.mouse.down(); await page.waitForTimeout(70); await page.mouse.up(); };
  const scrollTo = async (sel, offset = 90) => {
    await page.evaluate(([s, o]) => {
      const el = document.querySelector(s);
      const top = el.getBoundingClientRect().top + scrollY - o;
      (window.__lenis ? window.__lenis.scrollTo(top, { duration: 1.4 }) : scrollTo({ top, behavior: 'smooth' }));
    }, [sel, offset]);
    await page.waitForTimeout(1600);
  };
  await page.goto(SITE + url, { waitUntil: 'networkidle', timeout: 90000 });
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(600);
  await act({ page, move, point, click, scrollTo, wait: ms => page.waitForTimeout(ms) });
  const video = page.video();
  await ctx.close();
  const file = await video.path();
  renameSync(file, join(OUT, `${name}.webm`));
  for (const f of readdirSync(dir)) renameSync(join(dir, f), join(dir, `old-${f}`));
  console.log(`recorded ${name}`);
}

// 3 · The same screen fitted to each persona, switched with the tabs
await scene('fitting', '/', async ({ page, click, scrollTo, wait, move }) => {
  await scrollTo('.fitting-room', 70);
  await move(700, 560); await wait(1600);
  const tab = n => page.locator('[role=tablist][aria-label="Fit for persona"] [role=tab]').nth(n);
  await click(tab(1)); await wait(2600);
  await move(1380, 640); await wait(900);
  await click(tab(2)); await wait(2600);
  await move(1420, 900); await wait(1000);
  await click(tab(0)); await wait(1800);
});

// 4–5 · A real recorded fal run replayed in the Studio: candidates arrive, the archive fills
await scene('baste', '/gui/?persona=cyberbotanist&tab=generate', async ({ page, click, scrollTo, wait, point }) => {
  await wait(900);
  await click(page.getByLabel('Dry run')); await wait(700);
  await click(page.getByRole('button', { name: /generate|cut/i }).last());
  await wait(1200);
  await scrollTo('#gen-progress', 120);
  await wait(9000);
  await point(page.locator('.archive-map-grid')); await wait(7000);
}, { demo: true });

await scene('cut', '/gui/?persona=cyberbotanist&tab=generate', async ({ page, click, scrollTo, wait, point }) => {
  await click(page.getByLabel('Dry run')); await wait(300);
  await click(page.getByRole('button', { name: /generate|cut/i }).last());
  await page.waitForFunction(() => /Finished/.test(document.querySelector('#gen-progress')?.textContent ?? ''), null, { timeout: 60000 });
  await scrollTo('.archive-map', 100); await wait(1200);
  await scrollTo('#gen-progress + * ~ div h3, h3', 100);
  await page.evaluate(() => { const h = [...document.querySelectorAll('h3')].find(e => /The cut/.test(e.textContent)); h?.scrollIntoView({ behavior: 'smooth', block: 'start' }); });
  await wait(1800);
  await point(page.locator('video').first()); await wait(2500);
  await page.mouse.wheel(0, 420); await wait(2600);
}, { demo: true });

// 6 · Tokens tab: the design system as code
await scene('tokens', '/gui/?persona=nightmarketcoder&tab=tokens', async ({ page, wait, point, click }) => {
  await wait(1500);
  const tabs = page.getByRole('tab', { name: /tailwind|panda|css/i });
  if (await tabs.count()) { await click(tabs.nth(1)); await wait(1500); await click(tabs.nth(0)); }
  await point(page.locator('pre, code').first()); await wait(3000);
});

// 7 · Ask the persona why
await scene('talk', '/#meet', async ({ page, click, scrollTo, wait, point }) => {
  await scrollTo('#meet', 70);
  await click(page.locator('#talk-nightmarketcoder')); await wait(1600);
  const ask = page.locator('.companion-suggestions button').first();
  await click(ask); await wait(7000);
  await point(page.locator('.companion-log')); await wait(1200);
  const next = page.locator('.companion-suggestions button').first();
  await click(next); await wait(7000);
});

// 8 · Bring your own: the Studio's new-persona form
await scene('yours', '/gui?new=1', async ({ page, wait, point }) => {
  await wait(1200);
  const field = page.locator('input, textarea').first();
  if (await field.count()) { await point(field); await wait(400); await field.click(); await page.keyboard.type('A ceramicist who listens to Arthur Russell', { delay: 45 }); }
  await wait(2500);
});

await browser.close();

