  run.brief = generatePrompts(basePersonas[p], asset).image.prompt;
  run.evolved = suite.assets.images[0].prompt;
  const bestIndex = suite.archive.reduce((b, c, i, a) => (c.quality > a[b].quality ? i : b), 0);
  const best = `site/public/assets/fittings/runs/${p}/best.webp`;
  execFileSync('magick', [suite.archive[bestIndex].path, '-resize', '1280x720^', '-gravity', 'center', '-extent', '1280x720', '-quality', '78', best]);
  run.best = { index: bestIndex, src: '/assets/fittings/runs/' + p + '/best.webp' };
  writeFileSync(`site/src/lib/runs/${p}.json`, JSON.stringify(run));
  execFileSync('rm', [pub]);
  console.log(p, 'best', bestIndex, run.candidates[bestIndex].quality);
}
