import { $, component$, sync$, useComputed$, useSignal, useStyles$, useVisibleTask$ } from "@builder.io/qwik";
import Tempus from "tempus";
import type { CandidateSummary } from "~/lib/api-types";
import type { RecordedRun } from "~/lib/recorded-runs";
import { DEMO_PERSONAS, DEMO_TOKENS } from "~/lib/demo-data";
import { voiceOf } from "~/lib/converse";
import { ShaderCanvas } from "~/components/fx/shader-canvas";
import cyberbotanist from "~/lib/runs/cyberbotanist.json";
import nightmarketcoder from "~/lib/runs/nightmarketcoder.json";
import liminalweeb from "~/lib/runs/liminalweeb.json";
import styles from "./method-run.css?inline";

const RUNS: Record<string, RecordedRun> = {
  cyberbotanist: cyberbotanist as RecordedRun,
  nightmarketcoder: nightmarketcoder as RecordedRun,
  liminalweeb: liminalweeb as RecordedRun,
};
const ORDER = ["cyberbotanist", "nightmarketcoder", "liminalweeb"];

/** The engine's archive bins: colour temperature (−1…1) and density (0…1), five each. */
const BINS = 5;
const bin = (v: number, min: number, max: number) => Math.min(BINS - 1, Math.max(0, Math.floor(((v - min) / (max - min)) * BINS)));
/** Stable 0–1 noise from an index, for the hand-tossed tilt of each slide. */
const jitter = (n: number) => {
  let h = Math.imul(n + 0x9e37, 0x85ebca6b);
  h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
};

/** When each slide lands, as a fraction of the pinned scroll (see method-run.css). */
const LAND_START = 0.04;
const LAND_STEP = 0.021;
const LAND_SPAN = 0.07;

interface Slide {
  c: CandidateSummary;
  i: number;
  x: number;
  y: number;
  /** Position in its pile, 0 at the bottom. */
  k: number;
  top: boolean;
  kept: boolean;
  best: boolean;
  tilt: number;
}

/** Lay one run out on the table: each archive cell is a pile, the judge's favourite on top. */
function layout(run: RecordedRun): Slide[] {
  const piles = new Map<string, number[]>();
  run.candidates.forEach((c, i) => {
    const key = `${bin(c.features[0], -1, 1)}:${bin(c.features[1], 0, 1)}`;
    piles.set(key, [...(piles.get(key) ?? []), i]);
  });
  const slides: Slide[] = [];
  for (const [key, members] of piles) {
    const [x, y] = key.split(":").map(Number);
    // Kept candidates rise to the top of their pile, then by score.
    const order = [...members].sort((a, b) => {
      const ca = run.candidates[a], cb = run.candidates[b];
      return Number(!!ca.cell) - Number(!!cb.cell) || ca.quality - cb.quality;
    });
    order.forEach((i, k) => {
      const c = run.candidates[i];
      slides[i] = { c, i, x, y, k: Math.min(k, 6), top: k === order.length - 1, kept: !!c.cell, best: i === run.best.index, tilt: c.cell ? (jitter(i) - 0.5) * 3 : (jitter(i) - 0.5) * 9 };
    });
  }
  return slides;
}

const CRITERIA: Array<[keyof CandidateSummary["criteria"] & string, string]> = [
  ["personaAlignment", "Persona alignment"],
  ["visualQuality", "Visual quality"],
  ["uniqueness", "Uniqueness"],
  ["coherence", "Coherence"],
  ["usability", "Usability"],
];

/**
 * The /method hero: one real Baste run on a darkroom light table. As the page
 * scrolls (Lenis, pinned), the twenty-four drafts land where the vision judge
 * placed them — cool to warm, sparse to dense — then get scored, and only the
 * best in each direction stays on top. Switch person to watch the search move
 * to a different region of the map. Reduced motion and narrow screens show the
 * finished table.
 */
export const MethodRun = component$(() => {
  useStyles$(styles);
  const active = useSignal(ORDER[0]);
  const landed = useSignal(24);
  const root = useSignal<HTMLElement>();

  const run = useComputed$(() => RUNS[active.value]);
  const slides = useComputed$(() => layout(RUNS[active.value]));

  // Count landed drafts from the pinned progress, for the live counter.
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    const el = root.value;
    if (!el) return;
    const resolved = () => window.matchMedia("(prefers-reduced-motion: reduce), (max-width: 959px)").matches;
    let last = -1;
    const remove = Tempus.add(() => {
      const p = resolved() ? 1 : Number(el.style.getPropertyValue("--pin") || 0);
      const n = Math.max(0, Math.min(24, Math.floor((p - LAND_START - LAND_SPAN / 2) / LAND_STEP) + 1));
      if (n !== last) landed.value = last = n;
    }, { label: "method-run" });
    cleanup(remove);
  });

  const pick = $((id: string) => { active.value = id; });

  const r = run.value;
  const persona = DEMO_PERSONAS.find((p) => p.id === active.value)!;
  const t = DEMO_TOKENS[active.value];
  const handle = voiceOf(active.value).handle;
  const best = r.candidates[r.best.index];
  const kept = r.candidates.filter((c) => c.cell).length;
  const shown = Math.min(landed.value, r.candidates.length);
  const generation = shown ? r.candidates[shown - 1].generation : 0;
  const bestSlide = slides.value[r.best.index];
  const quote = best.feedback.split(/(?<=[.!?])\s+/).slice(0, 2).join(" ");
  const stops = [
    { color: "#0d0b0a", position: 0 },
    { color: t.colors.primary, position: 0.55 },
    { color: t.colors.accent, position: 1 },
  ];

  return (
    <section ref={root} class="method-run" data-pin aria-labelledby="method-title" style={{ "--persona-primary": t.colors.primary, "--persona-accent": t.colors.accent }}>
      <div class="method-run-stage">
        <div class="method-run-copy">
          <a href="/#meet" class="method-run-back">← Back to the personas</a>
          <span class="label method-run-kicker">The method · a real run</span>
          <h1 id="method-title" class="display">Twenty-four drafts for one person.</h1>
          <p class="method-run-lede">
            Not a diagram. Baste drafted a brief from {handle}’s measurements, tried twenty-four versions across colour
            temperature and density, had a vision model judge every one, and kept the best of each direction.
          </p>

          <div role="tablist" aria-label="Whose run" class="method-run-tabs">
            {ORDER.map((id) => {
              const p = DEMO_PERSONAS.find((x) => x.id === id)!;
              const selected = id === active.value;
              return (
                <button
                  key={id}
                  type="button"
                  role="tab"
                  id={`run-${id}`}
                  aria-selected={selected}
                  aria-controls="method-run-table"
                  tabIndex={selected ? 0 : -1}
                  data-juice="pin"
                  class="method-run-tab"
                  style={{ "--tab-accent": DEMO_TOKENS[id].colors.accent }}
                  onClick$={() => pick(id)}
                  onKeyDown$={[sync$((event: KeyboardEvent) => {
                    if (["ArrowRight", "ArrowLeft", "Home", "End"].includes(event.key)) event.preventDefault();
                  }), $(async (event: KeyboardEvent) => {
                    const i = ORDER.indexOf(id);
                    const n = event.key === "Home" ? 0 : event.key === "End" ? ORDER.length - 1 : event.key === "ArrowRight" ? (i + 1) % ORDER.length : event.key === "ArrowLeft" ? (i + ORDER.length - 1) % ORDER.length : -1;
                    if (n < 0) return;
                    await pick(ORDER[n]);
                    document.getElementById(`run-${ORDER[n]}`)?.focus();
                  })]}
                >
                  <img src={`/assets/companions/${id}.webp`} alt="" width={32} height={32} loading="lazy" decoding="async" />
                  <span>{voiceOf(id).handle}<small>{p.name.replace(/^The /, "")}</small></span>
                </button>
              );
            })}
          </div>

          <ol class="method-run-steps">
            <li class="method-run-step" data-step="1">
              <strong>Baste</strong>
              <span>Loose drafts land where the judge says they sit: cool to warm, sparse to dense.</span>
            </li>
            <li class="method-run-step" data-step="2">
              <strong>Fit</strong>
              <span>Each one is scored for persona alignment, quality, uniqueness, coherence and usability.</span>
            </li>
            <li class="method-run-step" data-step="3">
              <strong>Cut</strong>
              <span>Only the best in each direction stays on top. You get the spread, not one guess.</span>
            </li>
          </ol>

          <p class="method-run-counter" aria-live="off">
            <strong>{shown}</strong>/{r.candidates.length} judged · generation <strong>{generation}</strong> of {r.generations} ·{" "}
            <strong>{kept}</strong> kept
          </p>
        </div>

        <div class="method-run-table-wrap">
          <div
            id="method-run-table"
            role="tabpanel"
            aria-labelledby={`run-${active.value}`}
            class="method-run-table"
            data-best-side={bestSlide.x >= 3 ? "left" : "right"}
          >
            <ShaderCanvas
              class="method-run-glow"
              fallback={`radial-gradient(60% 70% at 70% 30%, color-mix(in oklab, ${t.colors.primary} 34%, transparent), transparent 70%), radial-gradient(50% 60% at 20% 80%, color-mix(in oklab, ${t.colors.accent} 22%, transparent), transparent 70%), #0d0b0a`}
              layers={[
                { type: "SolidColor", id: "ground", props: { color: "#0d0b0a" } },
                { type: "MeshGradient", id: "glow", props: { stops, count: 4, smoothness: 2.4, variation: 0.3, swirl: 0.25, drift: 0.18, speed: 0.25, opacity: 0.42 } },
                { type: "FilmGrain", id: "grain", props: { strength: 0.35, animated: true } },
              ]}
              live={{ glow: { stops } }}
            />
            <div class="method-run-grid" aria-hidden="true">
              {Array.from({ length: BINS * BINS }, (_, n) => <i key={n} />)}
            </div>
            <span class="method-run-axis method-run-axis--x" aria-hidden="true"><span>cool</span><span>colour temperature</span><span>warm</span></span>
            <span class="method-run-axis method-run-axis--y" aria-hidden="true">sparse → dense</span>

            <ul class="method-run-slides" aria-label={`${r.candidates.length} drafts for ${handle}, placed by colour temperature and density`}>
              {slides.value.map((s) => (
                <li
                  key={s.i}
                  class="method-run-slide"
                  data-top={s.top ? "true" : "false"}
                  data-kept={s.kept ? "true" : "false"}
                  data-best={s.best ? "true" : "false"}
                  style={{ "--x": s.x, "--y": s.y, "--k": s.k, "--i": s.i, "--tilt": `${s.tilt.toFixed(2)}deg` }}
                >
                  <img
                    src={s.c.url}
                    alt={s.kept ? `Kept draft, generation ${s.c.generation}, judged ${s.c.quality.toFixed(2)}` : ""}
                    width={480}
                    height={270}
                    loading={active.value === ORDER[0] ? "eager" : "lazy"}
                    decoding="async"
                  />
                  <span class="method-run-score">{s.c.quality.toFixed(2)}</span>
                </li>
              ))}
            </ul>

            <figure class="method-run-loupe">
              <img src={r.best.src} alt={`${handle}'s highest-scoring draft`} width={1280} height={720} loading="lazy" decoding="async" />
              <figcaption>
                <span class="method-run-loupe-head">
                  <span class="label">Kept · generation {best.generation}</span>
                  <strong>{best.quality.toFixed(2)}</strong>
                </span>
                <dl>
                  {CRITERIA.map(([key, label]) => (
                    <div key={key}>
                      <dt>{label}</dt>
                      <dd><i style={{ width: `${Math.round((best.criteria[key] ?? 0) * 100)}%` }} /><span>{(best.criteria[key] ?? 0).toFixed(2)}</span></dd>
                    </div>
                  ))}
                </dl>
                <blockquote>“{quote}”<cite>— the judge, looking at the image</cite></blockquote>
              </figcaption>
            </figure>
          </div>
          <p class="method-run-note">
            Real output from <code>baste generate {persona.id} --provider fal</code>: Seedream drafts, judged by Gemini through fal.
            Piles are archive cells; the number is the judge’s score.
          </p>
        </div>
      </div>
    </section>
  );
});

/* ─── Method hero: a real run on a darkroom light table ──────────────────────
   One number drives the whole scene: --p, the pinned scroll progress that
   fx/smooth-scroll publishes as --pin. Every phase is derived from it in CSS,
   so nothing animates on its own and scrolling back rewinds the run.
     land   each draft drops onto the table in the order it was generated
     judge  scores appear; buried drafts dim and their piles tighten
     cut    the best in each direction is stitched; the overall pick is enlarged
   Reduced motion and narrow screens show the finished table (--p: 1). */

.method-run {
  --nav-h: 61px;
  --p: var(--pin, 0);
  --judge: clamp(0, calc((var(--p) - 0.62) / 0.12), 1);
  --cut: clamp(0, calc((var(--p) - 0.78) / 0.12), 1);
  position: relative;
}
@media (min-width: 960px) and (prefers-reduced-motion: no-preference) {
  .method-run { height: 290vh; }
  .method-run-stage { position: sticky; top: var(--nav-h); height: calc(100vh - var(--nav-h)); }
}
@media (max-width: 959px), (prefers-reduced-motion: reduce) {
  .method-run { --p: 1; }
}

.method-run-stage {
  box-sizing: border-box;
  max-width: 1400px; margin: 0 auto;
  padding: clamp(16px, 3vh, 36px) clamp(16px, 2.5vw, 36px);
  display: grid; grid-template-columns: minmax(290px, 0.68fr) minmax(0, 1.6fr);
  gap: clamp(24px, 3vw, 48px); align-items: center;
}

/* Copy column */
.method-run-copy { display: flex; flex-direction: column; gap: clamp(10px, 1.8vh, 18px); min-width: 0; }
.method-run-back { color: #2F55A4; font-size: 14px; text-decoration: none; }
.method-run-back:hover { text-decoration: underline; text-underline-offset: 4px; }
.method-run-kicker { color: #A9311E; }
.method-run h1 { font-size: clamp(38px, 4.2vw, 66px); line-height: 0.98; text-wrap: balance; margin: 0; }
.method-run-lede { margin: 0; font-size: clamp(15px, 1.15vw, 17px); line-height: 1.55; color: #45423C; max-width: 44ch; }

.method-run-tabs { display: flex; gap: 6px; flex-wrap: wrap; }
.method-run-tab {
  display: inline-flex; align-items: center; gap: 8px; padding: 4px 12px 4px 4px; min-height: 42px;
  border: 1px solid #CFC7B8; border-radius: 999px; background: #FBF9F4; color: #1C1B19;
  font: inherit; font-size: 13px; font-weight: 600; text-align: left;
  transition: background .25s var(--ease-thread), border-color .25s var(--ease-thread), color .25s var(--ease-thread);
}
.method-run-tab img { width: 32px; height: 32px; border-radius: 50%; object-fit: cover; }
.method-run-tab span { display: flex; flex-direction: column; line-height: 1.1; }
.method-run-tab small { font-weight: 400; font-size: 11px; color: #6E6A61; }
.method-run-tab:hover { border-color: #1C1B19; }
.method-run-tab[aria-selected="true"] { background: #1C1B19; border-color: #1C1B19; color: #F1ECE2; }
.method-run-tab[aria-selected="true"] small { color: #CFC7B8; }
.method-run-tab[aria-selected="true"] img { box-shadow: 0 0 0 2px #1C1B19, 0 0 0 3.5px var(--tab-accent); }
.method-run-tab:focus-visible { outline: 2px solid #2F55A4; outline-offset: 3px; }

.method-run-steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; counter-reset: step; }
.method-run-step {
  --a: 0;
  position: relative; display: grid; grid-template-columns: 64px 1fr; gap: 10px; padding: 9px 0 9px 14px;
  font-size: 14px; line-height: 1.45; color: #45423C;
  opacity: calc(0.4 + var(--a) * 0.6);
}
.method-run-step strong { font-family: "Bodoni Moda", Georgia, serif; font-size: 19px; font-weight: 500; color: #1C1B19; line-height: 1.2; }
.method-run-step::before {
  content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 2px; border-radius: 2px;
  background: #D2402A; transform-origin: top; transform: scaleY(var(--a));
}
.method-run-step[data-step="1"] { --a: calc(1 - var(--judge)); }
.method-run-step[data-step="2"] { --a: calc(var(--judge) * (1 - var(--cut))); }
.method-run-step[data-step="3"] { --a: var(--cut); }
@media (max-width: 959px), (prefers-reduced-motion: reduce) {
  .method-run-step { --a: 1 !important; opacity: 1; }
  .method-run-step::before { background: #CFC7B8; }
}
.method-run-counter { margin: 0; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 12px; color: #6E6A61; }
.method-run-counter strong { color: #1C1B19; font-weight: 600; }

/* The light table */
.method-run-table-wrap { display: flex; flex-direction: column; gap: 10px; min-width: 0; align-items: center; }
.method-run-table {
  position: relative; overflow: hidden; isolation: isolate;
  width: min(100%, calc((100vh - var(--nav-h) - 120px) * 1.42));
  aspect-ratio: 1.42;
  border-radius: 18px;
  background: #0d0b0a;
  box-shadow: 0 1px 0 rgba(28,27,25,.08), 0 40px 70px -40px rgba(20,14,8,.75), inset 0 0 0 1px rgba(255,255,255,.04);
}
.method-run-glow { z-index: 0; }
.method-run-grid, .method-run-slides { position: absolute; inset: 18px 18px 40px 40px; }
.method-run-grid { z-index: 1; display: grid; grid-template-columns: repeat(5, 1fr); grid-template-rows: repeat(5, 1fr); }
.method-run-grid i { border-right: 1px dashed rgba(201, 212, 236, .12); border-bottom: 1px dashed rgba(201, 212, 236, .12); }
.method-run-grid i:nth-child(5n) { border-right: 0; }
.method-run-grid i:nth-child(n + 21) { border-bottom: 0; }
.method-run-axis {
  position: absolute; z-index: 2; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 10px;
  letter-spacing: .14em; text-transform: uppercase; color: rgba(201, 212, 236, .7);
}
.method-run-axis--x { left: 40px; right: 18px; bottom: 13px; display: flex; justify-content: space-between; }
.method-run-axis--y { left: 13px; top: 18px; bottom: 40px; writing-mode: vertical-rl; transform: rotate(180deg); text-align: center; }

.method-run-slides { z-index: 3; list-style: none; margin: 0; padding: 0; }
.method-run-slide {
  --land: clamp(0, calc((var(--p) - (0.04 + var(--i) * 0.021)) / 0.07), 1);
  --tuck: calc(1 - var(--judge) * 0.6);
  position: absolute;
  left: calc(var(--x) * 20% + 1.6%);
  top: calc((4 - var(--y)) * 20% + 2.4%);
  width: 16.8%;
  z-index: calc(var(--k) + 1);
  padding: 4px 4px 9px;
  background: #F4EFE6;
  border-radius: 3px;
  box-shadow: 0 1px 0 rgba(0,0,0,.3), 0 10px 18px -10px rgba(0,0,0,.8);
  opacity: var(--land);
  translate: calc(var(--k) * 6px * var(--tuck)) calc(var(--k) * -5px * var(--tuck) + (1 - var(--land)) * -46px);
  scale: calc(1 + (1 - var(--land)) * 0.14);
  rotate: calc(var(--tilt) * (1 - var(--cut) * 0.6));
  transition: left .75s var(--ease-thread), top .75s var(--ease-thread);
  transition-delay: calc(var(--i) * 14ms);
}
.method-run-slide img { display: block; width: 100%; aspect-ratio: 16 / 10; object-fit: cover; border-radius: 1px; background: #2a2622; }
.method-run-slide[data-top="false"] { opacity: calc(var(--land) * (1 - var(--judge) * 0.5) * (1 - var(--cut) * 0.4)); }
.method-run-slide[data-top="true"][data-kept="false"] { opacity: calc(var(--land) * (1 - var(--cut) * 0.5)); }
.method-run-slide[data-kept="true"] { z-index: 20; }
.method-run-slide[data-best="true"] { z-index: 30; scale: calc(1 + (1 - var(--land)) * 0.14 + var(--cut) * 0.16); }
.method-run-slide::after {
  content: ""; position: absolute; inset: -5px; border-radius: 6px; pointer-events: none;
  border: 1.5px dashed #F0715A; opacity: 0;
}
.method-run-slide[data-kept="true"]::after { opacity: var(--cut); }
.method-run-score {
  position: absolute; left: 7px; bottom: 13px; padding: 0 4px; border-radius: 2px;
  font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 10px; line-height: 1.5;
  background: rgba(13, 11, 10, .82); color: #F4EFE6;
  opacity: var(--judge);
}
.method-run-slide[data-top="false"] .method-run-score { display: none; }

/* The loupe: the judge's pick, enlarged, with its scores and verdict */
.method-run-loupe {
  position: absolute; z-index: 40; margin: 0; pointer-events: none;
  top: 18px; width: 40%;
  display: flex; flex-direction: column;
  background: #F4EFE6; color: #1C1B19; border-radius: 10px; overflow: hidden;
  box-shadow: 0 30px 50px -24px rgba(0,0,0,.85), 0 0 0 1px rgba(0,0,0,.2);
  opacity: var(--cut);
  translate: 0 calc((1 - var(--cut)) * 18px);
}
.method-run-table[data-best-side="right"] .method-run-loupe { right: 18px; }
.method-run-table[data-best-side="left"] .method-run-loupe { left: 40px; }
.method-run-table[data-best-side="bottom"] .method-run-loupe {
  top: auto; bottom: 46px; left: 40px; width: min(66%, 720px); flex-direction: row; align-items: stretch;
}
.method-run-table[data-best-side="bottom"] .method-run-loupe img { width: 48%; aspect-ratio: auto; object-fit: cover; }
.method-run-loupe img { display: block; width: 100%; aspect-ratio: 16 / 9; object-fit: cover; }
.method-run-loupe figcaption { display: flex; flex-direction: column; gap: 8px; padding: 12px 14px 14px; flex: 1; min-width: 0; }
.method-run-loupe-head { display: flex; justify-content: space-between; align-items: baseline; }
.method-run-loupe-head .label { color: #A9311E; }
.method-run-loupe-head strong { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 18px; }
.method-run-loupe dl { margin: 0; display: grid; gap: 3px; }
.method-run-loupe dl div { display: grid; grid-template-columns: 112px 1fr; align-items: center; gap: 8px; font-size: 11.5px; }
.method-run-loupe dt { color: #6E6A61; }
.method-run-loupe dd { margin: 0; display: grid; grid-template-columns: 1fr 30px; align-items: center; gap: 6px; }
.method-run-loupe dd i { display: block; height: 5px; border-radius: 3px; background: linear-gradient(90deg, var(--persona-primary), var(--persona-accent)); }
.method-run-loupe dd span { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 10.5px; text-align: right; }
.method-run-loupe blockquote { margin: 0; font-family: "Bodoni Moda", Georgia, serif; font-size: 14px; line-height: 1.35; font-style: italic; color: #1C1B19; }
.method-run-loupe cite { display: block; margin-top: 4px; font-family: "IBM Plex Mono", ui-monospace, monospace; font-style: normal; font-size: 10px; letter-spacing: .08em; text-transform: uppercase; color: #6E6A61; }

.method-run-note { margin: 0; font-size: 12px; color: #6E6A61; max-width: 92ch; text-align: center; }
.method-run-note code { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 11.5px; color: #1C1B19; }

/* Narrow screens: copy, then the finished table, then the pick below it */
@media (max-width: 959px) {
  .method-run-stage { grid-template-columns: minmax(0, 1fr); padding-top: 28px; padding-bottom: 48px; }
  .method-run-table { width: 100%; overflow: visible; }
  .method-run-grid, .method-run-slides { inset: 10px 10px 30px 28px; }
  .method-run-axis--x { left: 28px; right: 10px; bottom: 9px; font-size: 9px; }
  .method-run-axis--y { left: 7px; top: 10px; bottom: 30px; font-size: 9px; }
  .method-run-slide { padding: 2px 2px 5px; }
  .method-run-score { display: none; }
  .method-run-loupe,
  .method-run-table[data-best-side] .method-run-loupe {
    position: relative; inset: auto; width: 100%; margin-top: 14px; flex-direction: column;
  }
  .method-run-table[data-best-side="bottom"] .method-run-loupe img { width: 100%; aspect-ratio: 16 / 9; }
  .method-run-table-wrap { gap: 0; }
  .method-run-note { margin-top: 12px; text-align: left; }
}
@media (prefers-reduced-motion: reduce) {
  .method-run-slide { transition: none; }
}

