import { chromium } from 'playwright';
const [,, w='1440', h='900', tag='a'] = process.argv;
const b = await chromium.launch({ executablePath: '/usr/bin/google-chrome', args: ['--enable-unsafe-webgpu', '--enable-features=Vulkan', '--use-angle=vulkan'] });
const mobile = +w < 600;
const p = await b.newPage({ viewport: { width: +w, height: +h }, isMobile: mobile, hasTouch: mobile });
const logs = [];
p.on('pageerror', e => logs.push('pageerror: ' + e.message));
p.on('console', m => { if (m.type() === 'error') logs.push('console: ' + m.text().slice(0, 240)); });
await p.goto('http://127.0.0.1:5173/method/', { waitUntil: 'networkidle', timeout: 90000 });
await p.evaluate(() => document.fonts.ready);
await p.waitForTimeout(1500);
const span = await p.evaluate(() => { const el = document.querySelector('.method-run'); return el.offsetHeight - innerHeight; });
// Jump to progress points without Lenis smoothing.
const at = async (frac, name) => {
  await p.evaluate(y => { (window.__lenis ? window.__lenis.scrollTo(y, { immediate: true }) : window.scrollTo(0, y)); }, Math.round(span * frac));
  await p.waitForTimeout(900);
  await p.screenshot({ path: `mr-${tag}-${w}-${name}.png` });
  return p.evaluate(() => ({ pin: getComputedStyle(document.querySelector('.method-run')).getPropertyValue('--pin'), counter: document.querySelector('.method-run-counter')?.textContent?.trim(), shader: document.querySelector('[data-shader-state]')?.getAttribute('data-shader-state') }));
};
if (mobile) { await p.screenshot({ path: `mr-${tag}-${w}-full.png`, fullPage: false }); await p.evaluate(() => window.scrollTo(0, 640)); await p.waitForTimeout(800); await p.screenshot({ path: `mr-${tag}-${w}-scrolled.png` }); }
else {
  console.log('start', JSON.stringify(await at(0, '0')));
  console.log('mid', JSON.stringify(await at(0.35, '35')));
  console.log('judge', JSON.stringify(await at(0.7, '70')));
  console.log('cut', JSON.stringify(await at(0.98, '98')));
}
console.log('span', span, logs.join('\n'));
await b.close();
EOF
