import { $, component$, sync$, useComputed$, useSignal, useStyles$, useVisibleTask$ } from "@builder.io/qwik";
import Tempus from "tempus";
import type { RecordedRun } from "~/lib/recorded-runs";
import { DEMO_PERSONAS, DEMO_TOKENS } from "~/lib/demo-data";
import { voiceOf } from "~/lib/converse";
import { ShaderCanvas } from "~/components/fx/shader-canvas";
import cyberbotanist from "~/lib/runs/cyberbotanist.json";
import nightmarketcoder from "~/lib/runs/nightmarketcoder.json";
import liminalweeb from "~/lib/runs/liminalweeb.json";
import styles from "./method-run.css?inline";

const RUNS: Record<string, RecordedRun> = {
  cyberbotanist: cyberbotanist as RecordedRun,
  nightmarketcoder: nightmarketcoder as RecordedRun,
  liminalweeb: liminalweeb as RecordedRun,
};
const ORDER = ["cyberbotanist", "nightmarketcoder", "liminalweeb"];

/** Scroll phases, as fractions of the pinned span. Keep in step with method-run.css. */
const LAND_START = 0.04;
const LAND_STEP = 0.021;
const LAND_SPAN = 0.07;
const JUDGE_START = 0.62;
const CUT_START = 0.78;

const CRITERIA: Array<[string, string]> = [
  ["personaAlignment", "Persona alignment"],
  ["visualQuality", "Visual quality"],
  ["uniqueness", "Uniqueness"],
  ["coherence", "Coherence"],
  ["usability", "Usability"],
];

/** Where the judge placed a draft, in words. */
function direction(f: number[]): string {
  const temp = f[0] <= -0.33 ? "cool" : f[0] >= 0.33 ? "warm" : "neutral";
  const density = f[1] >= 0.75 ? "dense" : f[1] <= 0.35 ? "sparse" : "balanced";
  return `${temp} · ${density}`;
}

const VARIATION = /^- (.+) (color temperature|visual density|rendering)$/gm;
const variation = (brief: string) =>
  [...brief.matchAll(VARIATION)].map((m) => ({ value: m[1], axis: m[2] === "color temperature" ? "colour" : m[2] === "visual density" ? "density" : "rendering" }));

/** The parts of a drafted brief worth reading in a hero: subject, variation, references. */
function readBrief(run: RecordedRun) {
  const lines = run.brief.split("\n");
  const subject = lines[0].replace(/^Stunning hero image:\s*/, "").replace(/^Hero image for /, "");
  const elements = lines.find((l) => l.includes("Core visual elements"))?.replace(/^- Core visual elements:\s*/, "") ?? "";
  const nod = lines.find((l) => l.startsWith("Create something")) ?? "";
  const final = variation(run.evolved);
  return { subject, elements, nod, axes: variation(run.brief).map((s, i) => ({ ...s, final: final[i]?.value ?? s.value })) };
}

/** A hand-drawn grease-pencil loop that overshoots where it closes. */
const LOOP = "M10 46 C 6 20, 40 5, 104 6 C 170 7, 196 22, 194 44 C 192 70, 150 84, 98 83 C 42 82, 4 70, 8 40 C 10 26, 30 14, 58 9";

/**
 * The /method hero: one real Baste run as a darkroom contact sheet. As the page
 * scrolls (Lenis, pinned), six generations of drafts develop strip by strip,
 * the judge's scores appear on the film edge, and grease pencil circles the
 * drafts Baste kept — the best in each direction it explored. Every frame is
 * real output and opens to the judge's notes. Reduced motion and narrow
 * screens get the finished sheet.
 */
export const MethodRun = component$(() => {
  useStyles$(styles);
  const active = useSignal(ORDER[0]);
  const selected = useSignal<number | null>(null);
  const landed = useSignal(24);
  const phase = useSignal<"land" | "judge" | "cut">("cut");
  const root = useSignal<HTMLElement>();

  const strips = useComputed$(() => {
    const byGeneration = new Map<number, number[]>();
    RUNS[active.value].candidates.forEach((c, i) => byGeneration.set(c.generation, [...(byGeneration.get(c.generation) ?? []), i]));
    return [...byGeneration.entries()].sort((a, b) => a[0] - b[0]);
  });

  // Follow the pinned progress for the live counter and the phase wording.
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    const el = root.value;
    if (!el) return;
    const settled = window.matchMedia("(prefers-reduced-motion: reduce), (max-width: 959px)");
    let last = "";
    const remove = Tempus.add(() => {
      const p = settled.matches ? 1 : Number(el.style.getPropertyValue("--pin") || 0);
      const n = Math.max(0, Math.min(24, Math.floor((p - LAND_START - LAND_SPAN / 2) / LAND_STEP) + 1));
      const ph = p >= CUT_START ? "cut" : p >= JUDGE_START ? "judge" : "land";
      if (`${n}:${ph}` === last) return;
      last = `${n}:${ph}`;
      landed.value = n;
      phase.value = ph;
    }, { label: "method-run" });
    cleanup(() => remove?.());
  });

  const pick = $((id: string) => {
    active.value = id;
    selected.value = null;
  });

  const run = RUNS[active.value];
  const t = DEMO_TOKENS[active.value];
  const handle = voiceOf(active.value).handle;
  const brief = readBrief(run);
  const keptOrder = new Map<number, number>();
  run.candidates.forEach((c, i) => { if (c.cell) keptOrder.set(i, keptOrder.size); });
  const shown = Math.min(landed.value, run.candidates.length);
  const generation = shown ? run.candidates[shown - 1].generation : 0;
  const focus = selected.value ?? run.best.index;
  const draft = run.candidates[focus];
  const quote = draft.feedback.split(/(?<=[.!?])\s+/).slice(0, 2).join(" ");
  const stops = [
    { color: "#0c0a09", position: 0 },
    { color: "#4a100b", position: 0.45 },
    { color: t.colors.primary, position: 0.8 },
    { color: t.colors.accent, position: 1 },
  ];

  return (
    <section ref={root} class="method-run" data-pin aria-labelledby="method-title" style={{ "--persona-primary": t.colors.primary, "--persona-accent": t.colors.accent }}>
      <div class="method-run-stage">
        <div class="method-run-copy">
          <a href="/#meet" class="method-run-back">← Back to the personas</a>
          <span class="label method-run-kicker">The method · one real run</span>
          <h1 id="method-title" class="display">Twenty-four drafts for one person.</h1>
          <p class="method-run-lede">
            Every frame on this sheet is a real draft from one Baste run for {handle}: six generations of four, each
            scored by a vision model that looked at it. The circled frames are what Baste kept, the best in each
            direction it explored.
          </p>

          <div role="tablist" aria-label="Whose run" class="method-run-tabs">
            {ORDER.map((id) => {
              const isActive = id === active.value;
              return (
                <button
                  key={id}
                  type="button"
                  role="tab"
                  id={`run-${id}`}
                  aria-selected={isActive}
                  aria-controls="method-run-sheet"
                  tabIndex={isActive ? 0 : -1}
                  title={DEMO_PERSONAS.find((p) => p.id === id)!.name}
                  data-juice="pin"
                  class="method-run-tab"
                  style={{ "--tab-accent": DEMO_TOKENS[id].colors.accent }}
                  onClick$={() => pick(id)}
                  onKeyDown$={[sync$((event: KeyboardEvent) => {
                    if (["ArrowRight", "ArrowLeft", "Home", "End"].includes(event.key)) event.preventDefault();
                  }), $(async (event: KeyboardEvent) => {
                    const i = ORDER.indexOf(id);
                    const n = event.key === "Home" ? 0 : event.key === "End" ? ORDER.length - 1 : event.key === "ArrowRight" ? (i + 1) % ORDER.length : event.key === "ArrowLeft" ? (i + ORDER.length - 1) % ORDER.length : -1;
                    if (n < 0) return;
                    await pick(ORDER[n]);
                    document.getElementById(`run-${ORDER[n]}`)?.focus();
                  })]}
                >
                  <img src={`/assets/companions/${id}.webp`} alt="" width={30} height={30} loading="lazy" decoding="async" />
                  {voiceOf(id).handle}
                </button>
              );
            })}
          </div>

          <ol class="method-run-steps">
            <li data-step="1"><strong>Baste</strong><span>Each generation nudges the brief cooler or warmer, sparser or denser, and drafts four more.</span></li>
            <li data-step="2"><strong>Fit</strong><span>A vision model scores every draft for fit, quality, uniqueness, coherence and usability.</span></li>
            <li data-step="3"><strong>Cut</strong><span>Only the best in each direction is kept. You choose from the spread, not one guess.</span></li>
          </ol>

          <p class="method-run-counter">
            {phase.value === "cut"
              ? <><strong>{keptOrder.size}</strong> kept from <strong>{run.candidates.length}</strong> drafts · {run.generations} generations</>
              : <><strong>{shown}</strong>/{run.candidates.length} {phase.value === "judge" ? "judged" : "developed"} · generation <strong>{generation}</strong> of {run.generations}</>}
          </p>
        </div>

        <div class="method-run-table-wrap">
          <div class="method-run-table">
            <ShaderCanvas
              class="method-run-glow"
              fallback={`radial-gradient(70% 60% at 30% 0%, rgba(150, 30, 20, .35), transparent 70%), radial-gradient(60% 60% at 90% 100%, color-mix(in oklab, ${t.colors.accent} 16%, transparent), transparent 70%), #0c0a09`}
              layers={[
                { type: "SolidColor", id: "ground", props: { color: "#0c0a09" } },
                { type: "MeshGradient", id: "safelight", props: { stops, count: 4, smoothness: 2.6, variation: 0.28, swirl: 0.2, drift: 0.14, speed: 0.22, opacity: 0.5 } },
                { type: "FilmGrain", id: "grain", props: { strength: 0.12, animated: true } },
              ]}
              live={{ safelight: { stops } }}
            />

            <div id="method-run-sheet" role="tabpanel" aria-labelledby={`run-${active.value}`} class="method-run-sheet">
              <p class="method-run-hint" aria-hidden="true">Scroll to develop the run <span>↓</span></p>
              {strips.value.map(([g, indices]) => (
                <div key={`${active.value}-${g}`} class="method-run-strip">
                  <span class="method-run-edge" aria-hidden="true"><span>BASTE ▸ GEN {g}</span><span>{active.value.toUpperCase()}</span></span>
                  <ol class="method-run-frames" aria-label={`Generation ${g}`}>
                    {indices.map((i) => {
                      const c = run.candidates[i];
                      const k = keptOrder.get(i);
                      const best = i === run.best.index;
                      return (
                        <li
                          key={i}
                          class="method-run-frame"
                          data-kept={k !== undefined ? "true" : "false"}
                          data-best={best ? "true" : "false"}
                          style={{ "--i": i, "--k": k ?? 0, "--loop-tilt": `${((i * 37) % 7) - 3}deg` }}
                        >
                          <button
                            type="button"
                            class="method-run-frame-button"
                            aria-pressed={selected.value === i}
                            aria-label={`Draft ${i + 1}, generation ${g}, judged ${c.quality.toFixed(2)}${k !== undefined ? ", kept" : ""}. Show the judge's notes.`}
                            onClick$={() => (selected.value = selected.value === i ? null : i)}
                          >
                            <img src={c.url} alt="" width={480} height={270} loading="lazy" decoding="async" />
                          </button>
                          <span class="method-run-frame-edge" aria-hidden="true">
                            <span>{String(i + 1).padStart(2, "0")}A</span>
                            <span class="method-run-frame-score">{c.quality.toFixed(2)}</span>
                          </span>
                          {k !== undefined && (
                            <svg class="method-run-loop" viewBox="0 0 200 90" preserveAspectRatio="none" aria-hidden="true">
                              <path d={LOOP} pathLength={1} />
                            </svg>
                          )}
                          {best && <span class="method-run-pick" aria-hidden="true">pick</span>}
                        </li>
                      );
                    })}
                  </ol>
                </div>
              ))}
            </div>

            <div class="method-run-panel" data-selected={selected.value !== null ? "true" : "false"}>
              <article class="method-run-brief" aria-label="The brief">
                <span class="label">The brief</span>
                <p class="method-run-brief-from">Drafted from {handle}’s measurements</p>
                <p class="method-run-brief-subject">{brief.subject}</p>
                <dl class="method-run-brief-axes">
                  <dt>Variation <small>seed → kept hero</small></dt>
                  {brief.axes.map((a) => (
                    <dd key={a.axis} data-moved={a.final !== a.value ? "true" : "false"}>
                      <span class="method-run-brief-axis">{a.axis}</span>
                      <span class="method-run-brief-seed">{a.value}</span>
                      {a.final !== a.value && <span class="method-run-brief-final">→ {a.final}</span>}
                    </dd>
                  ))}
                </dl>
                <p class="method-run-brief-refs">{brief.elements}</p>
                <p class="method-run-brief-nod">{brief.nod}</p>
              </article>

              <figure class="method-run-loupe" aria-live="polite">
                <img src={focus === run.best.index ? run.best.src : draft.url} alt={`Draft ${focus + 1} for ${handle}`} width={1280} height={720} loading="lazy" decoding="async" />
                <figcaption>
                  <span class="method-run-loupe-head">
                    <span class="label">Draft {focus + 1} · gen {draft.generation} · {draft.cell ? `kept, ${direction(draft.features)}` : "not kept"}</span>
                    <strong>{draft.quality.toFixed(2)}</strong>
                  </span>
                  <dl>
                    {CRITERIA.map(([key, label]) => (
                      <div key={key}>
                        <dt>{label}</dt>
                        <dd><i style={{ width: `${Math.round((draft.criteria[key] ?? 0) * 100)}%` }} /><span>{(draft.criteria[key] ?? 0).toFixed(2)}</span></dd>
                      </div>
                    ))}
                  </dl>
                  <blockquote>“{quote}”<cite>— the judge, looking at the image</cite></blockquote>
                  {selected.value !== null && (
                    <button type="button" class="method-run-loupe-close" onClick$={() => (selected.value = null)}>
                      {focus === run.best.index ? "Close" : "Back to the pick"}
                    </button>
                  )}
                </figcaption>
              </figure>
            </div>
          </div>
          <p class="method-run-note">
            Real output from <code>baste generate {active.value} --provider fal</code> · Seedream drafts, judged by Gemini through fal.
            Select any frame to read the judge’s notes.
          </p>
        </div>
      </div>
    </section>
  );
});

/* ─── Method hero: one real run as a darkroom contact sheet ──────────────────
   One number drives the scene: --p, the pinned scroll progress that
   fx/smooth-scroll publishes as --pin. Every phase derives from it in CSS, so
   nothing plays on its own and scrolling back rewinds the run.
     develop  each draft develops on its film strip in the order it was made
     judge    the judge's score prints on the film edge under each frame
     cut      grease pencil circles the kept drafts; the brief gives way to the pick
   Without room to pin, or with reduced motion, the finished sheet shows (--p: 1).
   Phase timings match LAND_*, JUDGE_START and CUT_START in method-run.tsx. */

.method-run {
  --nav-h: 61px;
  --p: var(--pin, 0);
  --judge: clamp(0, calc((var(--p) - 0.62) / 0.12), 1);
  --cut: clamp(0, calc((var(--p) - 0.78) / 0.12), 1);
  --amber: #E3A548;
  --grease: #EF4A33;
  position: relative;
}
@media (min-width: 1180px) and (min-height: 700px) and (prefers-reduced-motion: no-preference) {
  .method-run { height: 290vh; }
  .method-run-stage { position: sticky; top: var(--nav-h); height: calc(100vh - var(--nav-h)); }
  .method-run-table { --tw: min(100cqw, calc((100vh - var(--nav-h) - 110px) * 1.4)); }
}
@media not ((min-width: 1180px) and (min-height: 700px) and (prefers-reduced-motion: no-preference)) {
  .method-run { --p: 1; }
  .method-run-hint { display: none; }
}

.method-run-stage {
  box-sizing: border-box;
  max-width: 1440px; margin: 0 auto;
  padding: clamp(18px, 3vh, 36px) clamp(16px, 2.5vw, 36px);
  display: grid; grid-template-columns: minmax(300px, 0.62fr) minmax(0, 1.6fr);
  gap: clamp(24px, 3vw, 52px); align-items: center;
}
@media (max-width: 1179px) {
  .method-run-stage { grid-template-columns: minmax(0, 1fr); padding-top: 32px; padding-bottom: 56px; }
}

/* ── Copy ── */
.method-run-copy { display: flex; flex-direction: column; gap: clamp(10px, 1.7vh, 18px); min-width: 0; }
.method-run-back { color: #2F55A4; font-size: 14px; text-decoration: none; width: fit-content; }
.method-run-back:hover { text-decoration: underline; text-underline-offset: 4px; }
.method-run-kicker { color: #A9311E; }
.method-run h1 { font-size: clamp(40px, 4.3vw, 68px); line-height: 0.98; text-wrap: balance; margin: 0; }
.method-run-lede { margin: 0; font-size: clamp(15px, 1.12vw, 17px); line-height: 1.55; color: #45423C; max-width: 46ch; }

.method-run-tabs { display: flex; gap: 6px; flex-wrap: wrap; }
.method-run-tab {
  display: inline-flex; align-items: center; gap: 8px; padding: 4px 14px 4px 4px; min-height: 40px;
  border: 1px solid #CFC7B8; border-radius: 999px; background: #FBF9F4; color: #1C1B19;
  font: inherit; font-size: 14px; font-weight: 600;
  transition: background .25s var(--ease-thread), border-color .25s var(--ease-thread), color .25s var(--ease-thread);
}
.method-run-tab img { width: 30px; height: 30px; border-radius: 50%; object-fit: cover; }
.method-run-tab:hover { border-color: #1C1B19; }
.method-run-tab[aria-selected="true"] { background: #1C1B19; border-color: #1C1B19; color: #F1ECE2; }
.method-run-tab[aria-selected="true"] img { box-shadow: 0 0 0 2px #1C1B19, 0 0 0 3.5px var(--tab-accent); }
.method-run-tab:focus-visible { outline: 2px solid #2F55A4; outline-offset: 3px; }

.method-run-steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.method-run-steps li {
  --a: 0;
  position: relative; display: grid; grid-template-columns: 62px 1fr; gap: 10px; padding: 8px 0 8px 14px;
  font-size: 14px; line-height: 1.45; color: #45423C;
  opacity: calc(0.38 + var(--a) * 0.62);
}
.method-run-steps strong { font-family: "Bodoni Moda", Georgia, serif; font-size: 19px; font-weight: 500; color: #1C1B19; line-height: 1.2; }
.method-run-steps li::before {
  content: ""; position: absolute; left: 0; top: 9px; bottom: 9px; width: 2px; border-radius: 2px;
  background: #D2402A; transform-origin: top; transform: scaleY(var(--a));
}
.method-run-steps [data-step="1"] { --a: calc(1 - var(--judge)); }
.method-run-steps [data-step="2"] { --a: calc(var(--judge) * (1 - var(--cut))); }
.method-run-steps [data-step="3"] { --a: var(--cut); }
@media not ((min-width: 1180px) and (min-height: 700px) and (prefers-reduced-motion: no-preference)) {
  .method-run-steps li { --a: 1 !important; opacity: 1; }
  .method-run-steps li::before { background: #CFC7B8; }
}
.method-run-counter { margin: 0; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 12px; color: #6E6A61; }
.method-run-counter strong { color: #1C1B19; font-weight: 600; }

/* ── The darkroom table: a contact sheet on the left, the brief or the pick on the right ── */
.method-run-table-wrap { container-type: inline-size; display: flex; flex-direction: column; align-items: center; gap: 10px; min-width: 0; }
.method-run-table {
  --tw: 100cqw;
  --u: calc(var(--tw) / 100);
  --paper: calc(1.3 * var(--u));
  --strip-x: calc(1.2 * var(--u));
  --gap: calc(0.75 * var(--u));
  --band: calc(1.15 * var(--u));
  --edge: calc(1.75 * var(--u));
  --frame-w: calc((54 * var(--u) - 2 * var(--paper) - 2 * var(--strip-x) - 3 * var(--gap)) / 4);
  position: relative; isolation: isolate; overflow: hidden;
  width: var(--tw);
  display: grid; grid-template-columns: calc(54 * var(--u)) minmax(0, 1fr);
  gap: calc(3 * var(--u)); align-items: start;
  padding: calc(2.4 * var(--u)) calc(2.6 * var(--u));
  box-sizing: border-box;
  border-radius: 18px;
  background: #0c0a09;
  box-shadow: 0 1px 0 rgba(28,27,25,.08), 0 40px 70px -40px rgba(20,14,8,.75), inset 0 0 0 1px rgba(255,255,255,.04);
}
.method-run-glow { z-index: -1; }

/* The print: cream paper, six film strips */
.method-run-sheet {
  position: relative; display: flex; flex-direction: column; gap: calc(0.9 * var(--u));
  padding: var(--paper); background: #EEE8DD; border-radius: 3px; rotate: -0.6deg;
  box-shadow: 0 1px 0 rgba(0,0,0,.4), 0 26px 40px -24px rgba(0,0,0,.9);
}
.method-run-hint {
  position: absolute; inset: 0; z-index: 5; margin: 0; display: grid; place-content: center; text-align: center; gap: 6px;
  font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 13px; letter-spacing: .12em; text-transform: uppercase; color: var(--amber);
  opacity: calc(1 - var(--p) * 28); pointer-events: none;
}
.method-run-hint span { font-size: 18px; animation: method-run-nudge 1.6s var(--ease-thread) infinite; }
@keyframes method-run-nudge { 50% { transform: translateY(5px); } }

.method-run-strip {
  position: relative; padding: var(--band) var(--strip-x) var(--edge); border-radius: 2px;
  background:
    radial-gradient(closest-side, #2d2826 70%, transparent 76%) 0 calc(var(--band) * 0.18) / calc(var(--band) * 1.15) calc(var(--band) * 0.62) repeat-x,
    radial-gradient(closest-side, #2d2826 70%, transparent 76%) 0 calc(100% - var(--edge) * 0.08) / calc(var(--band) * 1.15) calc(var(--band) * 0.62) repeat-x,
    #141110;
}
.method-run-edge {
  position: absolute; left: var(--strip-x); right: var(--strip-x); top: 0; height: var(--band);
  display: flex; justify-content: space-between; align-items: center;
  font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: clamp(7px, calc(0.68 * var(--u)), 10px); letter-spacing: .1em;
  color: var(--amber); opacity: .75; pointer-events: none;
}
.method-run-frames { list-style: none; margin: 0; padding: 0; display: flex; gap: var(--gap); }

.method-run-frame {
  --land: clamp(0, calc((var(--p) - (0.04 + var(--i) * 0.021)) / 0.07), 1);
  --scored: clamp(0, calc((var(--p) - (0.6 + var(--i) * 0.004)) / 0.05), 1);
  --drawn: clamp(0, calc((var(--p) - (0.78 + var(--k) * 0.012)) / 0.06), 1);
  position: relative; width: var(--frame-w); flex: none;
}
.method-run-frame-button {
  display: block; width: 100%; padding: 0; border: 0; border-radius: 1px; background: #050404;
  aspect-ratio: 16 / 10; overflow: hidden;
  transition: transform .25s var(--ease-thread), box-shadow .25s var(--ease-thread);
}
.method-run-frame-button img {
  display: block; width: 100%; height: 100%; object-fit: cover;
  opacity: var(--land);
  filter: sepia(calc((1 - var(--land)) * 0.9)) contrast(calc(1.35 - var(--land) * 0.35)) brightness(calc(0.35 + var(--land) * 0.65));
  scale: calc(1.06 - var(--land) * 0.06);
}
.method-run-frame[data-kept="false"] .method-run-frame-button { opacity: calc(1 - var(--cut) * 0.55); }
.method-run-frame-button:hover { transform: translateY(-2px); box-shadow: 0 6px 12px -6px rgba(0,0,0,.9); }
.method-run-frame-button:focus-visible { outline: 2px solid #F0C534; outline-offset: 2px; }
.method-run-frame-button[aria-pressed="true"] { outline: 2px solid #F0C534; outline-offset: 2px; }

.method-run-frame-edge {
  position: absolute; left: 0; right: 0; top: 100%; height: var(--edge);
  display: flex; justify-content: space-between; align-items: center;
  font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: clamp(7px, calc(0.72 * var(--u)), 11px);
  color: var(--amber); pointer-events: none;
}
.method-run-frame-edge > span:first-child { opacity: calc(var(--land) * 0.6); }
.method-run-frame-score { opacity: var(--scored); font-weight: 500; }
.method-run-frame[data-kept="true"] .method-run-frame-score { color: color-mix(in oklab, var(--amber), #fff calc(var(--cut) * 45%)); }

/* Grease pencil */
.method-run-loop {
  position: absolute; left: -12%; right: -12%; top: -22%; bottom: -34%; width: 124%; height: 156%;
  overflow: visible; pointer-events: none; rotate: var(--loop-tilt);
}
.method-run-loop path {
  fill: none; stroke: var(--grease); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
  stroke-dasharray: 1; stroke-dashoffset: calc(1 - var(--drawn));
  filter: drop-shadow(0 0 1px rgba(239, 74, 51, .5));
}
.method-run-pick {
  position: absolute; right: -4%; top: -38%; z-index: 2;
  font-family: "Bodoni Moda", Georgia, serif; font-style: italic; font-size: clamp(11px, calc(1.25 * var(--u)), 17px); font-weight: 600;
  color: var(--grease); rotate: -8deg; opacity: var(--cut); pointer-events: none;
}

/* ── Panel: the brief while the run develops, then the pick ── */
.method-run-panel { position: relative; align-self: stretch; min-height: 100%; }
.method-run-brief, .method-run-loupe {
  position: absolute; inset: 0 0 auto 0; box-sizing: border-box;
  background: #F6F1E7; color: #1C1B19; border-radius: 6px;
  box-shadow: 0 1px 0 rgba(0,0,0,.35), 0 26px 40px -24px rgba(0,0,0,.9);
}
.method-run-brief {
  display: flex; flex-direction: column; gap: 10px; padding: calc(1.7 * var(--u));
  rotate: 0.5deg;
