}
.method-run-brief .label { color: #A9311E; }
.method-run-brief p { margin: 0; }
.method-run-brief-from { font-size: 12px; color: #6E6A61; margin-top: -6px !important; }
.method-run-brief-subject { font-family: "Bodoni Moda", Georgia, serif; font-size: clamp(15px, calc(1.45 * var(--u)), 20px); line-height: 1.3; text-wrap: pretty; }
.method-run-brief-axes { margin: 0; display: grid; gap: 4px; padding: 10px 0; border-block: 1px dashed #CFC7B8; }
.method-run-brief-axes dt { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 10.5px; letter-spacing: .12em; text-transform: uppercase; color: #2F55A4; margin-bottom: 2px; }
.method-run-brief-axes dt small { letter-spacing: 0; text-transform: none; color: #6E6A61; margin-left: 6px; }
