}
.method-run-brief-axis { color: #6E6A61; grid-row: span 2; }
.method-run-brief-seed { text-decoration-line: line-through; text-decoration-color: rgb(210 64 42 / calc(var(--moved) * 100%)); text-decoration-thickness: 1.5px; }
.method-run-brief-axes dd[data-moved="false"] .method-run-brief-seed { text-decoration: none; }
.method-run-brief-final { color: #A9311E; opacity: var(--moved); }
.method-run-brief-refs { font-size: 13px; line-height: 1.5; color: #45423C; }
.method-run-brief-nod { font-size: 13px; line-height: 1.5; font-style: italic; color: #45423C; }

.method-run-loupe {
  margin: 0; overflow: hidden; display: flex; flex-direction: column;
  opacity: var(--cut); translate: 0 calc((1 - var(--cut)) * 16px);
  pointer-events: none;
}
.method-run-panel[data-selected="true"] .method-run-brief { opacity: 0; }
.method-run-panel[data-selected="true"] .method-run-loupe { opacity: 1; translate: none; pointer-events: auto; }
.method-run-loupe img { display: block; width: 100%; aspect-ratio: 16 / 9; object-fit: cover; background: #141110; }
.method-run-loupe figcaption { display: flex; flex-direction: column; gap: 9px; padding: calc(1.4 * var(--u)) calc(1.6 * var(--u)) calc(1.6 * var(--u)); }
.method-run-loupe-head { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; }
.method-run-loupe-head .label { color: #A9311E; }
.method-run-loupe-head strong { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 20px; }
.method-run-loupe dl { margin: 0; display: grid; gap: 3px; }
.method-run-loupe dl div { display: grid; grid-template-columns: minmax(0, 118px) 1fr; align-items: center; gap: 8px; font-size: 12px; }
.method-run-loupe dt { color: #6E6A61; }
.method-run-loupe dd { margin: 0; display: grid; grid-template-columns: 1fr 32px; align-items: center; gap: 6px; }
.method-run-loupe dd i { display: block; height: 5px; border-radius: 3px; background: linear-gradient(90deg, var(--persona-primary), var(--persona-accent)); }
.method-run-loupe dd span { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 11px; text-align: right; }
.method-run-loupe blockquote { margin: 0; font-family: "Bodoni Moda", Georgia, serif; font-size: clamp(14px, calc(1.2 * var(--u)), 16px); line-height: 1.38; font-style: italic; }
