.method-run-loupe-close:focus-visible { outline: 2px solid #2F55A4; outline-offset: 2px; }

.method-run-note { margin: 0; font-size: 12px; color: #6E6A61; text-align: center; max-width: 96ch; }
.method-run-note code { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 11.5px; color: #1C1B19; }

/* ── Narrow: the sheet across the full width, the pick and the brief beneath it ── */
@container (max-width: 760px) {
  .method-run-table {
    --frame-w: calc((100 * var(--u) - 5.2 * var(--u) - 2 * var(--paper) - 2 * var(--strip-x) - 3 * var(--gap)) / 4);
    --band: calc(2 * var(--u)); --edge: calc(3.4 * var(--u));
    grid-template-columns: minmax(0, 1fr); gap: 16px; padding: 12px; border-radius: 14px;
  }
  .method-run-sheet { rotate: none; }
  .method-run-edge { font-size: 7px; }
  .method-run-frame-edge { font-size: 8.5px; }
  .method-run-panel { display: grid; gap: 14px; }
  .method-run-brief, .method-run-loupe { position: relative; inset: auto; rotate: none; translate: none; opacity: 1; }
  .method-run-loupe { order: -1; }
  .method-run-panel[data-selected="true"] .method-run-brief { opacity: 1; }
  .method-run-brief { padding: 16px; }
  .method-run-loupe figcaption { padding: 14px 16px 16px; }
  .method-run-note { text-align: left; }
}

