    res: u("uRes"),
    time: u("uTime"),
    mouse: u("uMouse"),
    mouseAmt: u("uMouseAmt"),
    warp: u("uWarp"),
    weft: u("uWeft"),
    ground: u("uGround"),
    dye: u("uDye"),
    fold: u("uFold"),
    weave: u("uWeave"),
    thread: u("uThread"),
    scale: u("uScale"),
    scroll: u("uScroll"),
    grain: u("uGrain"),
    pattern: u("uPattern"),
    seed: u("uSeed"),
    density: u("uDensity"),
    pulse: u("uPulse"),
    tap: u("uTap"),
    hue: u("uHue"),
    colourSpace: u("uColourSpace"),
  };

