  let scale = initial.scale;
  let grain = initial.grain;

  const patterns = ["cloth", "flow", "moire", "contour", "marble", "radial"];
  let pattern = patterns.indexOf(initial.pattern ?? "cloth");
  let seed = initial.seed ?? 0,
    density = initial.density ?? 0.5,
