    const inside =
      e.clientX >= rect.left &&
      e.clientX <= rect.right &&
      e.clientY >= rect.top &&
      e.clientY <= rect.bottom;
    const aspect = rect.width / Math.max(1, rect.height);
    const ux = (e.clientX - rect.left) / rect.width;
    const uy = 1 - (e.clientY - rect.top) / rect.height;
