// Hash without sine (Dave Hoskins, MIT: shadertoy.com/view/4djSRW). The usual
// fract(sin(x) * 43758.5) amplifies last-bit rounding about ten-million-fold, so a
// lattice corner shared by two noise cells, reached through differently optimised
// expressions, could hash to unrelated values and tear the field along cell rows.
float hash(vec2 p) {
  p += vec2(uSeed * 0.013, uSeed * 0.021);
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

