input.content:
/* ─── Material lab: a live cloth on the cutting table, the swatch book beside it ───
   The preview stays in view (sticky) while the side column scrolls, so every
   change can be seen as it is made. Cursors come from global.css. */

.material-lab {
  --ml-rule: #CFC7B8;
  --ml-ink: #1C1B19;
  --ml-muted: #6E6A61;
  --ml-paper: #FBF9F4;
  --ml-thread: #D2402A;
  --ml-chalk: #2F55A4;
  --ml-top: calc(var(--nav-h, 61px) + 16px);
  color: var(--ml-ink);
  container-type: inline-size;
}
.material-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 400px);
  gap: clamp(20px, 2.6vw, 36px);
  align-items: start;
}
@container (max-width: 820px) {
  .material-layout { grid-template-columns: minmax(0, 1fr); }
}

/* ── The stage ── */
.material-stage { position: sticky; top: var(--ml-top); min-width: 0; display: flex; flex-direction: column; gap: 10px; }
@container (max-width: 820px) {
  .material-stage { position: relative; top: auto; }
}
.material-preview {
  position: relative;
  height: clamp(420px, calc(100vh - var(--ml-top) - 56px), 820px);
  overflow: hidden;
  isolation: isolate;
  border-radius: 4px;
  box-shadow: 0 1px 0 rgba(28, 27, 25, .08), 0 30px 50px -34px rgba(40, 28, 12, .6), inset 0 0 0 1px rgba(28, 27, 25, .06);
  /* cut from the bolt with pinking shears */
  --pink: 7px;
  -webkit-mask: linear-gradient(#000 0 0) top / 100% calc(100% - var(--pink)) no-repeat,
    conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) bottom / calc(var(--pink) * 2) calc(var(--pink) * 2) repeat-x;
  mask: linear-gradient(#000 0 0) top / 100% calc(100% - var(--pink)) no-repeat,
    conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) bottom / calc(var(--pink) * 2) calc(var(--pink) * 2) repeat-x;
}
@container (max-width: 820px) {
  .material-preview { height: auto; aspect-ratio: 4 / 5; max-height: 80vh; }
}
.material-preview canvas { position: absolute; inset: 0; display: block; width: 100%; height: 100%; }

.material-stage-name {
  position: absolute; left: 16px; top: 16px; z-index: 2;
  padding: 7px 12px 7px 26px; border-radius: 2px;
  background: #F6F1E7; color: var(--ml-ink);
  font-family: "Bodoni Moda", Georgia, serif; font-size: 17px; line-height: 1.1;
  box-shadow: 0 1px 0 rgba(0, 0, 0, .12), 0 8px 16px -10px rgba(0, 0, 0, .55);
  pointer-events: none;
}
.material-stage-name span { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 11px; color: var(--ml-muted); }
.material-stage-name::before {
  content: ""; position: absolute; left: 9px; top: 50%; width: 9px; height: 9px; margin-top: -4.5px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #F38A74, #D2402A 55%, #8E2615);
}
.material-stage-bar { position: absolute; right: 14px; top: 14px; z-index: 2; display: flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
.material-pill {
  min-height: 34px; padding: 6px 13px; border-radius: 999px;
  border: 1px solid rgba(28, 27, 25, .16);
  background: rgba(251, 249, 244, .88); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
  color: var(--ml-ink); font: inherit; font-size: 13px; font-weight: 600;
  transition: background .2s, border-color .2s;
}
.material-pill:hover { border-color: var(--ml-ink); }
.material-pill[aria-pressed="true"] { background: var(--ml-ink); color: #F1ECE2; border-color: var(--ml-ink); }
.material-pill:disabled { opacity: .5; }
.material-pill-primary { background: var(--ml-chalk); border-color: var(--ml-chalk); color: #F6F1E7; }
.material-pill-primary:hover { background: #23417E; border-color: #23417E; }

.material-type-sample {
  pointer-events: none; position: absolute; left: 5%; bottom: 7%; z-index: 1;
  max-width: min(86%, 520px); padding: 22px 26px;
  color: var(--ml-ink); background: #F1ECE2;
  box-shadow: 0 1px 0 rgba(0, 0, 0, .08), 0 18px 34px -24px rgba(0, 0, 0, .55);
}
.material-type-sample h2 {
  font-family: "Bodoni Moda", Georgia, serif; font-weight: 500;
  font-size: clamp(30px, 3.6vw, 58px); line-height: 1.02; letter-spacing: -0.03em; margin: 14px 0;
  text-wrap: balance;
}
.material-type-sample p { font-size: 14px; line-height: 1.6; margin: 0; }
.material-fallback {
  position: absolute; right: 16px; bottom: 24px; z-index: 2; max-width: 240px; margin: 0; padding: 12px;
  background: #F1ECE2; font-size: 13px;
}
.material-stage-note { margin: 0; font-size: 12.5px; color: var(--ml-muted); }

/* ── Side column ── */
.material-side { display: flex; flex-direction: column; gap: 18px; min-width: 0; }
.material-heading {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px;
  margin: 0 0 12px; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 11px; font-weight: 500;
  letter-spacing: .12em; text-transform: uppercase; color: var(--ml-chalk);
}
.material-heading small { font-family: "Instrument Sans", system-ui, sans-serif; font-size: 12px; letter-spacing: 0; text-transform: none; color: var(--ml-muted); font-weight: 400; }
.material-hint { margin: 8px 0 0; font-size: 12.5px; line-height: 1.5; color: var(--ml-muted); }

/* Swatch book: real cuttings of each cloth, rendered from the shader */
.material-swatches { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px 10px; }
.material-swatch {
  position: relative; display: flex; flex-direction: column; gap: 6px; padding: 0;
  border: 0; background: transparent; color: var(--ml-ink); font: inherit; text-align: left;
}
.material-swatch-fitted { grid-column: 1 / -1; flex-direction: row; align-items: stretch; gap: 12px; }
.material-swatch-cloth {
  position: relative; display: block; aspect-ratio: 4 / 5; overflow: hidden; border-radius: 2px;
  box-shadow: 0 1px 0 rgba(28, 27, 25, .1), 0 10px 16px -12px rgba(40, 28, 12, .7);
  --pink: 5px;
  -webkit-mask: linear-gradient(#000 0 0) top / 100% calc(100% - var(--pink)) no-repeat,
    conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) bottom / calc(var(--pink) * 2) calc(var(--pink) * 2) repeat-x;
  mask: linear-gradient(#000 0 0) top / 100% calc(100% - var(--pink)) no-repeat,
    conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) bottom / calc(var(--pink) * 2) calc(var(--pink) * 2) repeat-x;
  transition: transform .3s var(--ease-thread), box-shadow .3s var(--ease-thread);
}
.material-swatch-fitted .material-swatch-cloth { width: 34%; flex: none; }
.material-swatch-cloth img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: block; }
.material-swatch-tag { display: flex; flex-direction: column; gap: 1px; line-height: 1.2; }
.material-swatch-fitted .material-swatch-tag { justify-content: center; }
.material-swatch-tag span { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 10px; letter-spacing: .08em; text-transform: uppercase; color: var(--ml-muted); }
.material-swatch-tag strong { font-size: 13px; font-weight: 600; }
.material-swatch-fitted .material-swatch-tag span { color: var(--ml-thread); }
.material-swatch-fitted .material-swatch-tag strong { font-family: "Bodoni Moda", Georgia, serif; font-size: 19px; font-weight: 500; }
.material-swatch:hover .material-swatch-cloth { transform: translateY(-3px); }
.material-swatch[aria-pressed="true"] .material-swatch-cloth { box-shadow: 0 0 0 2px #F6F1E7, 0 0 0 4px var(--ml-thread), 0 12px 18px -12px rgba(40, 28, 12, .8); }
.material-swatch[aria-pressed="true"]::before {
  content: ""; position: absolute; z-index: 1; left: 50%; top: -5px; width: 11px; height: 11px; margin-left: -5.5px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #F38A74, #D2402A 55%, #8E2615); box-shadow: 0 2px 3px rgba(0, 0, 0, .35);
}
.material-swatch-fitted[aria-pressed="true"]::before { left: 17%; }
.material-swatch:focus-visible { outline: none; }
.material-swatch:focus-visible .material-swatch-cloth { outline: 2px solid var(--ml-chalk); outline-offset: 3px; }

/* The dye card */
.material-card {
  background: var(--ml-paper); border: 1px solid var(--ml-rule); border-radius: 4px; padding: 4px 20px;
  box-shadow: 0 1px 0 rgba(28, 27, 25, .05), 0 12px 26px -20px rgba(60, 45, 20, .45);
}
.material-group { border: 0; margin: 0; padding: 18px 0; min-width: 0; }
.material-group + .material-group { border-top: 1.5px dashed var(--ml-rule); }
.material-group > legend { float: left; width: 100%; padding: 0; }
.material-group > legend + * { clear: both; }

.material-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.material-chip {
  position: relative; display: inline-flex; align-items: center; min-height: 32px; padding: 5px 12px; border-radius: 999px;
  border: 1px solid #A79E8D; background: #F6F1E7; font-size: 13px;
  transition: background .2s, border-color .2s, color .2s;
}
.material-chip input, .material-blend input { position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none; }
.material-chip:hover { border-color: var(--ml-ink); }
.material-chip:has(input:checked) { background: var(--ml-ink); border-color: var(--ml-ink); color: #F1ECE2; }
.material-chip:has(input:focus-visible), .material-blend:has(input:focus-visible) { outline: 2px solid var(--ml-chalk); outline-offset: 2px; }

.material-wells { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.material-well { position: relative; display: flex; flex-direction: column; gap: 6px; }
.material-well input { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; border: 0; padding: 0; }
.material-well-chip {
  display: block; height: 46px; border-radius: 3px;
  box-shadow: inset 0 0 0 1px rgba(28, 27, 25, .16), 0 1px 0 rgba(255, 255, 255, .6);
  transition: background .25s;
}
.material-well:hover .material-well-chip { box-shadow: inset 0 0 0 1px rgba(28, 27, 25, .4); }
.material-well:has(input:focus-visible) .material-well-chip { outline: 2px solid var(--ml-chalk); outline-offset: 2px; }
.material-well-name { font-size: 12px; font-weight: 600; line-height: 1.2; }
.material-well-name small { display: block; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 10.5px; font-weight: 400; color: var(--ml-muted); }

.material-lots { display: flex; flex-wrap: wrap; gap: 6px; margin: 12px 0 4px; }
.material-lot {
  display: inline-flex; align-items: center; gap: 7px; min-height: 30px; padding: 4px 10px 4px 5px; border-radius: 999px;
  border: 1px solid var(--ml-rule); background: transparent; font: inherit; font-size: 12px; color: var(--ml-ink);
}
.material-lot:hover { border-color: var(--ml-ink); }
.material-lot > span { display: flex; border-radius: 999px; overflow: hidden; box-shadow: inset 0 0 0 1px rgba(28, 27, 25, .14); }
.material-lot i { display: block; width: 8px; height: 18px; }
.material-lot:focus-visible { outline: 2px solid var(--ml-chalk); outline-offset: 2px; }

.material-blends { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-top: 12px; }
.material-blend { position: relative; display: flex; flex-direction: column; gap: 5px; font-size: 12px; color: var(--ml-muted); }
.material-blend-bar {
  display: block; height: 22px; border-radius: 3px; box-shadow: inset 0 0 0 1px rgba(28, 27, 25, .14);
  background: linear-gradient(90deg, var(--a), var(--b), var(--c));
}
.material-blend-bar[data-space="oklab"] { background: linear-gradient(90deg in oklab, var(--a), var(--b), var(--c)); }
.material-blend-bar[data-space="hue"] { background: linear-gradient(90deg in hsl shorter hue, var(--a), var(--b), var(--c)); }
.material-blend:has(input:checked) { color: var(--ml-ink); font-weight: 600; }
.material-blend:has(input:checked) .material-blend-bar { box-shadow: 0 0 0 2px #F6F1E7, 0 0 0 3.5px var(--ml-thread); }

/* Tape-measure sliders with a dressmaker's pin */
.material-range { display: block; margin-top: 12px; font-size: 12.5px; font-weight: 600; }
.material-range > span { display: flex; justify-content: space-between; align-items: baseline; }
.material-range output { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 11px; font-weight: 400; color: var(--ml-muted); }
.material-range small { display: block; margin-top: 2px; font-size: 11.5px; font-weight: 400; color: var(--ml-muted); }
.material-range input[type="range"] {
  -webkit-appearance: none; appearance: none; display: block; width: 100%; height: 22px; margin: 4px 0 0; background: transparent;
}
.material-range input[type="range"]::-webkit-slider-runnable-track {
  height: 10px; border-radius: 2px;
  background: repeating-linear-gradient(90deg, rgba(28, 27, 25, .5) 0 1px, transparent 1px 7px) bottom / 100% 4px no-repeat, #F0C534;
  box-shadow: inset 0 0 0 1px rgba(28, 27, 25, .16);
}
.material-range input[type="range"]::-moz-range-track {
  height: 10px; border-radius: 2px;
  background: repeating-linear-gradient(90deg, rgba(28, 27, 25, .5) 0 1px, transparent 1px 7px) bottom / 100% 4px no-repeat, #F0C534;
  box-shadow: inset 0 0 0 1px rgba(28, 27, 25, .16);
}
.material-range input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none; width: 15px; height: 15px; margin-top: -2.5px; border: 0; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #F38A74, #D2402A 55%, #8E2615); box-shadow: 0 2px 3px rgba(0, 0, 0, .35);
}
.material-range input[type="range"]::-moz-range-thumb {
  width: 15px; height: 15px; border: 0; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #F38A74, #D2402A 55%, #8E2615); box-shadow: 0 2px 3px rgba(0, 0, 0, .35);
}
.material-range input[type="range"]:focus-visible { outline: 2px solid var(--ml-chalk); outline-offset: 3px; border-radius: 3px; }
.material-range input[type="range"]:disabled { opacity: .45; }

.material-toggle { display: flex; align-items: center; gap: 9px; margin-top: 14px; font-size: 13px; }
.material-toggle input { width: 16px; height: 16px; accent-color: var(--ml-thread); margin: 0; }

.material-seed { display: flex; align-items: flex-end; gap: 8px; }
.material-field { flex: 1; min-width: 0; display: block; font-size: 12.5px; font-weight: 600; }
.material-field input {
  display: block; width: 100%; height: 38px; margin-top: 6px; padding: 8px 10px; box-sizing: border-box;
  border: 1px solid #A79E8D; border-radius: 3px; background: #F6F1E7; font: inherit; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 14px;
}
.material-field input:focus-visible { outline: 2px solid var(--ml-chalk); outline-offset: 2px; }

/* Take it with you */
.material-take { padding: 18px 20px; border: 1px solid var(--ml-rule); border-radius: 4px; background: #F6F1E7; }
.material-take-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.material-take-row + .material-take-row { margin-top: 10px; padding-top: 10px; border-top: 1px dashed var(--ml-rule); }
.material-button {
  display: inline-flex; align-items: center; justify-content: center; min-height: 38px; padding: 8px 13px;
  font: inherit; font-size: 13px; font-weight: 600; color: var(--ml-ink);
  background: var(--ml-paper); border: 1px solid #A79E8D; border-radius: 3px;
}
.material-button:hover { background: #E9DFCB; border-color: var(--ml-ink); }
.material-button:disabled { opacity: .5; }
.material-button:focus-visible, .material-link:focus-visible, .material-pill:focus-visible { outline: 2px solid var(--ml-chalk); outline-offset: 2px; }
.material-button.act-chalk { color: var(--ml-chalk); border-color: #C9D4EC; }
.material-button.act-chalk:hover { border-color: var(--ml-chalk); background: #F3F5FB; }
.material-primary.act-chalk { color: #F6F1E7; background: var(--ml-chalk); border-color: var(--ml-chalk); }
.material-primary.act-chalk:hover { background: #23417E; }
.material-link { border: 0; background: transparent; padding: 6px 2px; font: inherit; font-size: 12.5px; color: #A9311E; text-decoration: underline; text-underline-offset: 3px; }
.material-status { min-height: 2.6em; margin: 12px 0 0; font-size: 12px; line-height: 1.5; color: var(--ml-muted); }

@media (prefers-reduced-motion: reduce) {
  .material-swatch-cloth, .material-well-chip, .material-chip { transition: none; }
}

