import { $, component$, useStyles$ } from "@builder.io/qwik";
import { DEMO_PERSONAS, DEMO_TOKENS } from "~/lib/demo-data";
import { voiceOf } from "~/lib/converse";
import {
  MATERIAL_PRESETS,
  MATERIAL_TECHNIQUES,
  MATERIAL_TRY_EVENT,
  materialForPersona,
  materialReason,
  personaSwatch,
  presetSwatch,
  type MaterialLook,
  type MaterialTry,
} from "~/lib/materials";
import styles from "./material-room.css?inline";

/** Hand a look to the workbench lab; the link itself scrolls there. */
const tryOn = $((id: string, name: string, look: MaterialLook) => {
  window.dispatchEvent(new CustomEvent<MaterialTry>(MATERIAL_TRY_EVENT, { detail: { id, name, look } }));
});

/** Bolts hang to slightly different lengths, like cloth on a rack. */
const LENGTHS = [1, 0.86, 0.95, 0.8, 0.97, 0.88];

/**
 * The material room's hero: the six studies hang from a rail as cut bolts of
 * cloth, rendered from the shader itself. Pick one and it goes onto the
 * workbench below.
 */
export const MaterialBolts = component$(() => {
  useStyles$(styles);
  return (
    <header class="mr-hero" aria-labelledby="mr-title">
      <div class="mr-hero-copy">
        <div>
          <span class="label mr-kicker">The material room</span>
          <h1 id="mr-title" class="display">The <em>cloth</em> under the interface.</h1>
        </div>
        <p class="mr-lede">
          Every persona’s interface sits on a material: woven from their palette, moving the way they move, textured like
          the places they love. Take a bolt off the rack to try it on, then bend it, re-dye it and keep it.
        </p>
      </div>
      <div class="mr-rack">
        <span class="mr-rail" aria-hidden="true" />
        <ol class="mr-bolts" aria-label="Material studies">
          {MATERIAL_PRESETS.map((p, i) => (
            <li key={p.id} class="mr-bolt" style={{ "--i": i, "--len": LENGTHS[i] }} data-depth={String([0.02, 0.05, 0.03, 0.06, 0.025, 0.045][i])}>
              <a href="#workbench" class="mr-bolt-link" data-juice="dye" data-dye={p.look.warp} onClick$={() => tryOn(p.id, p.name, p.look)}>
                <span class="mr-bolt-clip" aria-hidden="true" />
                <span class="mr-bolt-cloth">
                  <img src={presetSwatch(p.id)} alt="" width={400} height={500} loading={i < 3 ? "eager" : "lazy"} decoding="async" />
                </span>
                <span class="mr-bolt-tag">
                  <span>No. {String(i + 1).padStart(2, "0")}</span>
                  <strong>{p.name}</strong>
                  <small>{p.description}</small>
                  <em aria-hidden="true">Try it on ↓</em>
                </span>
              </a>
            </li>
          ))}
        </ol>
      </div>
    </header>
  );
});

const DYES = [
  ["ground", "Ground", "background"],
  ["warp", "First dye", "primary"],
  ["weft", "Second dye", "accent"],
] as const;

/**
 * How a persona becomes a cloth: technique from its aesthetic profile, dyes
 * from its generated palette, composition seeded by its name.
 */
export const PersonaCloths = component$(() => {
  useStyles$(styles);
  return (
    <section id="personas" class="mr-section" aria-labelledby="mr-personas">
      <header class="mr-section-head">
        <span class="label mr-kicker">Fitted cloth</span>
        <h2 id="mr-personas" class="display">Every persona weaves its own.</h2>
        <p>
          Baste chooses the technique from a persona’s aesthetic profile, dyes it with the palette it generated for them
          and seeds it with their name, so the same person always gets the same cloth. Change it in their Studio, and
          their header re-dyes to match.
        </p>
      </header>
      <div class="mr-personas">
        {DEMO_PERSONAS.map((p) => {
          const t = DEMO_TOKENS[p.id];
          const look = materialForPersona(p, t);
          const handle = voiceOf(p.id).handle;
          const swatch = personaSwatch(p.id, true);
          const dye = { ground: look.ground, warp: look.warp, weft: look.weft };
          return (
            <article key={p.id} class="mr-persona">
              <div class="mr-persona-cloth" style={{ background: look.ground }}>
                {swatch && <img src={swatch} alt={`${handle}'s cloth: ${MATERIAL_TECHNIQUES[look.pattern].name.toLowerCase()} in their palette`} width={960} height={600} loading="lazy" decoding="async" />}
                <img class="mr-persona-face" src={`/assets/companions/${p.id}.webp`} alt="" width={64} height={64} loading="lazy" decoding="async" />
              </div>
              <div class="mr-persona-body">
                <span class="mr-persona-meta">{handle} · {MATERIAL_TECHNIQUES[look.pattern].name}</span>
                <h3>{materialReason(p)}</h3>
                <dl class="mr-persona-dyes">
                  {DYES.map(([key, label, token]) => (
                    <div key={key}>
                      <dt><i style={{ background: dye[key] }} aria-hidden="true" />{label}</dt>
                      <dd><code>{dye[key].toUpperCase()}</code> <span>{token}</span></dd>
                    </div>
                  ))}
                </dl>
                <div class="mr-persona-actions">
                  <a href="#workbench" class="mr-button" data-juice="dye" data-dye={look.warp} onClick$={() => tryOn(`persona-${p.id}`, `${handle}'s cloth`, look)}>
                    Try it on
                  </a>
                  <a href={`/gui/?persona=${p.id}&tab=material`} class="mr-link">Open in the Studio <span aria-hidden="true">→</span></a>
                </div>
              </div>
            </article>
          );
        })}
      </div>
    </section>
  );
});

import { $, component$, useSignal, useStyles$ } from "@builder.io/qwik";
import styles from "./material-room.css?inline";

interface Study {
  id: string;
  name: string;
  description: string;
  motion?: boolean;
  files: Array<{ href: string; label: string; kind: string }>;
}

const DIR = "/materials/graphite";
const studies: Study[] = [
  {
    id: "chromatic-bath",
    name: "Chromatic bath",
    description: "Warm dye moves through a warped field. A cyclic colour ramp changes the light without replacing the composition.",
    motion: true,
    files: [
      { href: `${DIR}/chromatic-bath.graphite`, label: "Drawing", kind: "Graphite" },
      { href: `${DIR}/chromatic-bath-loop.graphite`, label: "Animated drawing", kind: "Graphite" },
      { href: `${DIR}/chromatic-bath-loop.mp4`, label: "Motion study", kind: "MP4" },
    ],
  },
  {
    id: "chalk-strata",
    name: "Chalk strata",
    description: "A repeated blue-and-paper ramp traces the same height field many times, building a landscape of contours.",
    files: [{ href: `${DIR}/chalk-strata.graphite`, label: "Drawing", kind: "Graphite" }],
  },
  {
    id: "radial-dye",
    name: "Radial dye",
    description: "A dyed strip repeats around a centre. Colour and rotation share a clock, so the whole fan turns together.",
    motion: true,
    files: [
      { href: `${DIR}/radial-dye.graphite`, label: "Drawing", kind: "Graphite" },
      { href: `${DIR}/radial-dye.svg`, label: "Vector", kind: "SVG" },
      { href: `${DIR}/radial-dye-loop.graphite`, label: "Animated drawing", kind: "Graphite" },
      { href: `${DIR}/radial-dye-pointer.graphite`, label: "Pointer-driven drawing", kind: "Graphite" },
      { href: `${DIR}/radial-dye-loop.mp4`, label: "Motion study", kind: "MP4" },
    ],
  },
  {
    id: "interference-weave",
    name: "Interference weave",
    description: "Two slightly rotated arrays create a slower rhythm where their threads cross. Small changes make large bands.",
    files: [
      { href: `${DIR}/interference-weave.graphite`, label: "Drawing", kind: "Graphite" },
      { href: `${DIR}/interference-weave.svg`, label: "Vector", kind: "SVG" },
    ],
  },
];

/** A motion study: a still until asked, then the loop plays (and pauses again on request). */
const MotionStudy = component$<{ study: Study }>(({ study }) => {
  const video = useSignal<HTMLVideoElement>();
  const playing = useSignal(false);
  const toggle = $(async () => {
    const v = video.value;
    if (!v) return;
    if (v.paused) {
      try {
        await v.play();
        playing.value = true;
      } catch {
        playing.value = false;
      }
    } else {
      v.pause();
      playing.value = false;
    }
  });
  return (
    <div class="mr-study-media">
      <video
        ref={video}
        src={study.files.find((f) => f.kind === "MP4")!.href}
        poster={`${DIR}/${study.id}.webp`}
        width={1024}
        height={640}
        muted
        loop
        playsInline
        preload="none"
        aria-label={`${study.name}, motion study`}
        onEnded$={() => (playing.value = false)}
      />
      <button type="button" class="mr-study-play" aria-pressed={playing.value} onClick$={toggle}>
        <span aria-hidden="true">{playing.value ? "❚❚" : "▶"}</span>
        {playing.value ? "Pause" : "Watch it move"}
      </button>
    </div>
  );
});

export const GraphiteStudies = component$(() => {
  useStyles$(styles);
  return (
    <section class="mr-section mr-graphite" aria-labelledby="graphite-studies">
      <header class="mr-section-head">
        <span class="label mr-kicker">From the Graphite workbench</span>
        <h2 id="graphite-studies" class="display">Four studies to take apart.</h2>
        <p>
          Native documents for{" "}
          <a href="https://graphite.rs" rel="noopener" target="_blank">Graphite</a>, the open-source node-based editor,
          picked from twenty variations. Open one to follow how the pattern is built, then change a node and make it yours.
        </p>
      </header>
      <div class="mr-studies">
        {studies.map((s) => (
          <article key={s.id} class="mr-study">
            {s.motion ? (
              <MotionStudy study={s} />
            ) : (
              <div class="mr-study-media">
                <img src={`${DIR}/${s.id}.webp`} width={1024} height={640} loading="lazy" decoding="async" alt={`${s.name}, a Graphite study`} />
              </div>
            )}
            <div class="mr-study-body">
              <h3>{s.name}</h3>
              <p>{s.description}</p>
              <ul class="mr-files" aria-label={`${s.name} downloads`}>
                {s.files.map((f) => (
                  <li key={f.href}>
                    <a href={f.href} download class="mr-file" data-juice="chalk">
                      <span>{f.kind}</span>
                      {f.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
});

/* ─── Material room: the rack of bolts, fitted cloth, and the Graphite studies ─── */

.mr-kicker { color: #A9311E; }

/* ── Hero: copy above a rail of hanging bolts ── */
.mr-hero { padding: clamp(28px, 5vh, 56px) 0 clamp(20px, 4vh, 40px); }
.mr-hero-copy {
  display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: clamp(20px, 4vw, 64px); align-items: end;
}
.mr-hero-copy h1 { margin: 14px 0 0; font-size: clamp(44px, 6.4vw, 96px); line-height: 0.96; text-wrap: balance; }
.mr-hero-copy h1 em { font-style: italic; color: #A9311E; }
.mr-lede { margin: 0; max-width: 44ch; font-size: clamp(16px, 1.3vw, 19px); line-height: 1.55; color: #45423C; }
@media (max-width: 860px) {
  .mr-hero-copy { grid-template-columns: minmax(0, 1fr); align-items: start; }
}

.mr-rack { position: relative; margin-top: clamp(28px, 5vh, 52px); padding-top: 14px; }
.mr-rail {
  position: absolute; left: -12px; right: -12px; top: 0; height: 9px; border-radius: 6px;
  background: linear-gradient(#D9D3C7, #9A9284 55%, #6F685C);
  box-shadow: 0 2px 0 rgba(255, 255, 255, .5) inset, 0 6px 10px -6px rgba(0, 0, 0, .45);
}
.mr-bolts { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: clamp(10px, 1.4vw, 22px); align-items: start; }
.mr-bolt { position: relative; translate: 0 var(--depth-y, 0); }
.mr-bolt-link { position: relative; display: flex; flex-direction: column; color: #1C1B19; text-decoration: none; transform-origin: 50% -14px; animation: mr-sway 7s ease-in-out infinite alternate; animation-delay: calc(var(--i) * -1.15s); }
.mr-bolt-link:hover { animation-play-state: paused; }
@keyframes mr-sway { from { rotate: -0.8deg; } to { rotate: 0.9deg; } }
.mr-bolt-clip {
  position: absolute; z-index: 2; left: 50%; top: -20px; width: 26px; height: 24px; margin-left: -13px;
  background: linear-gradient(90deg, #8C8477, #D7D1C4 45%, #8C8477); border-radius: 3px 3px 5px 5px;
  box-shadow: 0 3px 4px -2px rgba(0, 0, 0, .45);
}
.mr-bolt-clip::before { content: ""; position: absolute; left: 50%; top: -9px; width: 12px; height: 12px; margin-left: -6px; border: 2px solid #8C8477; border-bottom: 0; border-radius: 8px 8px 0 0; }
.mr-bolt-cloth {
  position: relative; display: block; overflow: hidden;
  aspect-ratio: 4 / calc(5 * var(--len));
  border-radius: 2px 2px 0 0;
  box-shadow: 0 1px 0 rgba(28, 27, 25, .1), 0 22px 30px -22px rgba(40, 28, 12, .75);
  --pink: 7px;
  -webkit-mask: linear-gradient(#000 0 0) top / 100% calc(100% - var(--pink)) no-repeat,
    conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) bottom / calc(var(--pink) * 2) calc(var(--pink) * 2) repeat-x;
  mask: linear-gradient(#000 0 0) top / 100% calc(100% - var(--pink)) no-repeat,
    conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) bottom / calc(var(--pink) * 2) calc(var(--pink) * 2) repeat-x;
  transition: transform .45s var(--ease-thread);
}
.mr-bolt-cloth img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; transition: transform 1.2s var(--ease-thread); }
.mr-bolt-cloth::after {
  /* the fold of the bolt over the rail */
  content: ""; position: absolute; inset: 0 0 auto; height: 18%;
  background: linear-gradient(rgba(0, 0, 0, .28), rgba(0, 0, 0, 0) 60%);
}
.mr-bolt-link:hover .mr-bolt-cloth { transform: translateY(6px); }
.mr-bolt-link:hover .mr-bolt-cloth img { transform: scale(1.06); }
.mr-bolt-tag { display: flex; flex-direction: column; gap: 2px; padding: 10px 2px 0; line-height: 1.25; }
.mr-bolt-tag span { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 10.5px; letter-spacing: .1em; color: #6E6A61; }
.mr-bolt-tag strong { font-family: "Bodoni Moda", Georgia, serif; font-size: clamp(16px, 1.35vw, 20px); font-weight: 500; }
.mr-bolt-tag small { font-size: 12.5px; color: #6E6A61; }
.mr-bolt-tag em { font-style: normal; font-size: 12.5px; font-weight: 600; color: #A9311E; opacity: 0; transform: translateY(-3px); transition: opacity .25s, transform .25s; }
.mr-bolt-link:hover .mr-bolt-tag em, .mr-bolt-link:focus-visible .mr-bolt-tag em { opacity: 1; transform: none; }
.mr-bolt-link:focus-visible { outline: none; }
.mr-bolt-link:focus-visible .mr-bolt-cloth { outline: 2px solid #2F55A4; outline-offset: 3px; }
@media (max-width: 960px) {
  .mr-bolts { grid-template-columns: repeat(3, minmax(0, 1fr)); row-gap: 30px; }
  .mr-rail { display: none; }
  .mr-bolt-clip { display: none; }
  .mr-bolt-tag small { display: none; }
}
@media (max-width: 520px) {
  .mr-bolts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .mr-bolt-cloth { aspect-ratio: 4 / 4.4; }
}
@media (prefers-reduced-motion: reduce) {
  .mr-bolt-link { animation: none; }
  .mr-bolt-cloth, .mr-bolt-cloth img { transition: none; }
}

/* ── Sections ── */
.mr-section { padding: clamp(56px, 9vh, 96px) 0 0; }
.mr-section-head { max-width: 640px; display: flex; flex-direction: column; gap: 14px; margin-bottom: clamp(24px, 4vh, 40px); }
.mr-section-head h2 { margin: 0; font-size: clamp(34px, 4.2vw, 56px); line-height: 1.02; text-wrap: balance; }
.mr-section-head p { margin: 0; font-size: 16px; line-height: 1.6; color: #45423C; }
.mr-section-head a { color: #A9311E; text-underline-offset: 3px; }

/* ── Fitted cloth ── */
.mr-personas { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(14px, 2vw, 28px); }
@media (max-width: 960px) { .mr-personas { grid-template-columns: minmax(0, 1fr); } }
.mr-persona { display: flex; flex-direction: column; background: #FBF9F4; border: 1px solid #CFC7B8; border-radius: 4px; overflow: hidden; box-shadow: 0 1px 0 rgba(28, 27, 25, .05), 0 16px 30px -24px rgba(60, 45, 20, .5); }
@media (max-width: 960px) { .mr-persona { flex-direction: row; } .mr-persona-cloth { width: 42%; flex: none; aspect-ratio: auto !important; } }
@media (max-width: 600px) { .mr-persona { flex-direction: column; } .mr-persona-cloth { width: auto; aspect-ratio: 16 / 10 !important; } }
.mr-persona-cloth { position: relative; aspect-ratio: 16 / 10; overflow: hidden; }
.mr-persona-cloth > img:first-child { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.mr-persona-face { position: absolute; left: 14px; bottom: -22px; width: 56px; height: 56px; border-radius: 50%; object-fit: cover; box-shadow: 0 0 0 3px #FBF9F4, 0 6px 12px -6px rgba(0, 0, 0, .6); z-index: 1; }
.mr-persona-cloth::after { content: ""; position: absolute; inset: auto 0 0; height: 22px; background: #FBF9F4; }
@media (max-width: 960px) and (min-width: 601px) { .mr-persona-cloth::after { display: none; } .mr-persona-face { bottom: 14px; } }
.mr-persona-body { display: flex; flex-direction: column; gap: 10px; padding: 34px 20px 20px; flex: 1; }
@media (max-width: 960px) and (min-width: 601px) { .mr-persona-body { padding-top: 20px; } }
.mr-persona-meta { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: #6E6A61; }
.mr-persona h3 { margin: 0; font-family: "Bodoni Moda", Georgia, serif; font-size: 21px; font-weight: 500; line-height: 1.22; text-wrap: balance; }
.mr-persona-dyes { margin: 4px 0 0; display: grid; gap: 5px; padding: 10px 0; border-block: 1px dashed #CFC7B8; }
.mr-persona-dyes div { display: grid; grid-template-columns: 108px 1fr; align-items: center; font-size: 12.5px; }
.mr-persona-dyes dt { display: flex; align-items: center; gap: 8px; color: #45423C; }
.mr-persona-dyes i { width: 16px; height: 16px; border-radius: 3px; box-shadow: inset 0 0 0 1px rgba(28, 27, 25, .15); }
.mr-persona-dyes dd { margin: 0; color: #6E6A61; }
.mr-persona-dyes code { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 11.5px; color: #1C1B19; }
.mr-persona-dyes dd span { font-size: 11.5px; }
.mr-persona-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 14px; margin-top: auto; padding-top: 6px; }
.mr-button {
  display: inline-flex; align-items: center; min-height: 38px; padding: 8px 15px; border-radius: 3px;
  background: #1C1B19; color: #F1ECE2; font-size: 13.5px; font-weight: 600; text-decoration: none;
  transition: background .2s;
}
.mr-button:hover { background: #A9311E; }
.mr-link { font-size: 13.5px; color: #2F55A4; text-decoration: none; }
.mr-link:hover { text-decoration: underline; text-underline-offset: 3px; }
.mr-button:focus-visible, .mr-link:focus-visible { outline: 2px solid #2F55A4; outline-offset: 3px; }

/* ── The workbench heading ── */
.mr-workbench { padding-top: clamp(56px, 9vh, 96px); scroll-margin-top: 70px; }

/* ── Graphite studies ── */
.mr-studies { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: clamp(20px, 2.4vw, 36px); }
@media (max-width: 760px) { .mr-studies { grid-template-columns: minmax(0, 1fr); } }
.mr-study { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.mr-study-media { position: relative; aspect-ratio: 16 / 10; overflow: hidden; border-radius: 3px; background: #E7E0D2; box-shadow: 0 1px 0 rgba(28, 27, 25, .06), 0 20px 34px -26px rgba(40, 28, 12, .7); }
.mr-study-media img, .mr-study-media video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: block; }
.mr-study-play {
  position: absolute; left: 14px; bottom: 14px; display: inline-flex; align-items: center; gap: 8px;
  min-height: 36px; padding: 6px 14px 6px 10px; border-radius: 999px; border: 0;
  background: rgba(28, 27, 25, .82); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
  color: #F6F1E7; font: inherit; font-size: 13px; font-weight: 600;
}
.mr-study-play span { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: #F6F1E7; color: #1C1B19; font-size: 9px; }
.mr-study-play:hover { background: #A9311E; }
.mr-study-play:focus-visible { outline: 2px solid #F0C534; outline-offset: 2px; }
.mr-study-body { display: flex; flex-direction: column; gap: 8px; }
.mr-study h3 { margin: 0; font-family: "Bodoni Moda", Georgia, serif; font-size: 26px; font-weight: 500; }
.mr-study p { margin: 0; font-size: 14.5px; line-height: 1.6; color: #45423C; max-width: 58ch; }
.mr-files { list-style: none; margin: 4px 0 0; padding: 0; display: flex; flex-wrap: wrap; gap: 6px; }
.mr-file {
  display: inline-flex; align-items: center; gap: 7px; min-height: 30px; padding: 4px 11px 4px 4px; border-radius: 999px;
  border: 1px solid #CFC7B8; background: #FBF9F4; color: #1C1B19; font-size: 12.5px; text-decoration: none;
  transition: border-color .2s, background .2s;
}
.mr-file span { padding: 2px 7px; border-radius: 999px; background: #E9DFCB; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 10px; letter-spacing: .06em; color: #45423C; }
.mr-file:hover { border-color: #2F55A4; background: #F3F5FB; }
.mr-file:focus-visible { outline: 2px solid #2F55A4; outline-offset: 2px; }

