/**
 * Narrate the Baste tour (videos/baste-tour) with fal TTS.
 * Lines come from videos/baste-tour/SCRIPT.md; each is generated once and cached.
 * Writes narration/<id>.mp3 and narration/timing.json, which the composition reads
 * to place each scene. The credential never enters an artifact.
 */
import { execFileSync } from 'node:child_process';
import { mkdir, readFile, writeFile, access } from 'node:fs/promises';
import { resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const project = resolve(root, 'videos/baste-tour');
const output = resolve(project, 'narration');
await mkdir(output, { recursive: true });
const key = process.env.FAL_KEY || (process.argv.includes('--skate')
  ? execFileSync('rtk', ['proxy', 'skate', 'get', 'fal_api_key@secrets'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim()
  : '');
if (!key) throw new Error('Set FAL_KEY or use --skate.');

// | # | id | scene | line |
const lines = (await readFile(resolve(project, 'SCRIPT.md'), 'utf8')).split('\n')
  .map(row => row.split('|').map(cell => cell.trim()))
  .filter(cells => /^\d+$/.test(cells[1] ?? ''))
  .map(cells => ({ id: cells[2], scene: cells[3], text: cells[4] }));
if (!lines.length) throw new Error('No narration lines found in SCRIPT.md.');

/** Pause before a scene's line, and breath after it, in seconds. */
const LEAD = 0.45;
const BREATH = 0.75;
const ffprobe = file => Number(execFileSync('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'default=noprint_wrappers=1:nokey=1', file], { encoding: 'utf8' }).trim());

let cursor = 0;
const timing = [];
for (const line of lines) {
  const audio = resolve(output, `${line.id}.mp3`);
  const metadata = resolve(output, `${line.id}.json`);
  let cached = false;
  try {
    await access(audio);
    cached = JSON.parse(await readFile(metadata, 'utf8')).text === line.text;
  } catch { /* generate below */ }
  if (!cached) {
    const response = await fetch('https://fal.run/fal-ai/elevenlabs/tts/multilingual-v2', {
      method: 'POST', redirect: 'error',
      headers: { Authorization: `Key ${key}`, 'Content-Type': 'application/json', 'X-Fal-Store-IO': '0' },
      body: JSON.stringify({ text: line.text, voice: 'Aria', stability: 0.6, similarity_boost: 0.75, speed: 1, language_code: 'en' }),
      signal: AbortSignal.timeout(120000),
    });
    if (!response.ok) {
      const error = await response.json().catch(() => ({}));
      throw new Error(error.detail === 'User is locked. Reason: TOP_UP.' ? 'fal needs a balance top-up before narration can be generated.' : `Narration ${line.id}: fal returned ${response.status}.`);
    }
    const data = await response.json();
    const url = new URL(data.audio.url);
    if (url.protocol !== 'https:' || !/(^|\.)fal\.media$/.test(url.hostname)) throw new Error('Unexpected audio host.');
    const media = await fetch(url, { redirect: 'error', signal: AbortSignal.timeout(30000) });
    if (!media.ok) throw new Error(`Audio download returned ${media.status}.`);
    await writeFile(audio, Buffer.from(await media.arrayBuffer()));
    await writeFile(metadata, JSON.stringify({ provider: 'fal', model: 'fal-ai/elevenlabs/tts/multilingual-v2', voice: 'Aria', text: line.text, requestId: response.headers.get('x-fal-request-id'), generatedAt: new Date().toISOString() }, null, 2) + '\n');
  }
  const voice = ffprobe(audio);
  const duration = Math.ceil((LEAD + voice + BREATH) * 30) / 30; // whole frames at 30fps
  timing.push({ id: line.id, scene: line.scene, text: line.text, start: +cursor.toFixed(3), duration: +duration.toFixed(3), voiceStart: +(cursor + LEAD).toFixed(3), voice: +voice.toFixed(3) });
  console.log(`${line.id}: ${voice.toFixed(2)}s voice → ${duration.toFixed(2)}s scene${cached ? ' (cached)' : ''}`);
  cursor += duration;
}
await writeFile(resolve(output, 'timing.json'), JSON.stringify({ voice: 'Aria', total: +cursor.toFixed(3), scenes: timing }, null, 2) + '\n');
console.log(`Tour narration: ${cursor.toFixed(2)}s`);

