cd ~/.cache/baste-shots && cat > scale-test.mjs <<'EOF'
import { chromium } from 'playwright';
import { writeFileSync } from 'node:fs';
const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', args: ['--enable-unsafe-webgpu', '--enable-features=Vulkan', '--use-angle=vulkan'] });
for (const mode of ['dpr2', 'scale2']) {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: mode === 'dpr2' ? 2 : 1 });
  const page = await ctx.newPage();
  await page.goto('http://127.0.0.1:5173/', { waitUntil: 'networkidle' });
  const cdp = await ctx.newCDPSession(page);
  if (mode === 'scale2') await cdp.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 2, mobile: false, scale: 1 });
  await page.evaluate(() => { const el = document.querySelector('.fitting-room'); el && scrollTo(0, el.getBoundingClientRect().top + scrollY - 76); });
  await page.waitForTimeout(1500);
  const frame = await new Promise(async (resolve) => {
    cdp.on('Page.screencastFrame', async (f) => { await cdp.send('Page.screencastFrameAck', { sessionId: f.sessionId }); resolve(f); });
    await cdp.send('Page.startScreencast', { format: 'png', maxWidth: 2880, maxHeight: 1800 });
  });
  await cdp.send('Page.stopScreencast');
  writeFileSync(`sheets/sc-${mode}.png`, Buffer.from(frame.data, 'base64'));
  console.log(mode, JSON.stringify(frame.metadata), await page.evaluate(() => [innerWidth, innerHeight, devicePixelRatio]));
  await ctx.close();
}
await browser.close();
EOF
timeout 120 env -u LD_LIBRARY_PATH node scale-test.mjs 2>&1 | tail -4; for m in dpr2 scale2; do ffprobe -v error -show_entries stream=width,height -of csv=p=0 sheets/sc-$m.png; done
